export const SCHOOLS: School[] = [
  { name: "ABC Pathways International Kindergarten", slug: "abc-pathways-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.abcpathways.co.th", description: "ABC Pathways is a British-curriculum kindergarten following the Cambridge framework, part of Bangkok's network of early years international schools that families use before transitioning to a primary school.\n\nFollowing the Cambridge framework specifically at the kindergarten level gives ABC Pathways a formal curriculum structure tied to the same examination board that many of Bangkok's British primary and secondary schools use later, creating some continuity for families planning ahead toward a Cambridge-aligned primary school.\n\nAs with Bangkok's other early years specialists, ABC Pathways functions as a starting point rather than a full K-12 school, meaning families will need to select a separate primary school once children complete the kindergarten stage.\n\nFamilies drawn to ABC Pathways are typically interested in that specific Cambridge framework grounding at the early years level, alongside standard considerations like location and campus atmosphere.", languageOfInstruction: "English", photo: "/images/schools/abc-pathways-international-kindergarten.jpg" },
  { name: "Anglo Singapore International School", slug: "anglo-singapore-international-school", curricula: ["British", "Singaporean"], budget: "over400k", website: "https://anglosingapore.ac.th", founded: 2003, description: "Founded in 2003 by Julie Sutanto with just four students on a single campus, Anglo Singapore has grown to three campuses across Bangkok and Nakhon Ratchasima, combining Cambridge IGCSE with the Singapore curriculum framework and offering High School Diploma, BTEC, and A-Level pathways.\n\nThat multi-pathway structure at the senior level, offering a genuine choice between an American-style diploma, the vocationally oriented BTEC, and traditional A-Levels, gives Anglo Singapore more flexibility than most Bangkok schools that commit to a single exam route.\n\nWith three campuses spanning both Bangkok and Nakhon Ratchasima, Anglo Singapore has expanded well beyond the city itself, giving it a regional footprint that few other Bangkok-founded international schools have built.\n\nFamilies drawn to Anglo Singapore are typically interested in that combination of Cambridge and Singapore curriculum elements alongside genuine choice in final qualification, whether academic, vocational, or the traditional British route.", languageOfInstruction: "English", feeRange: "385,800 to 798,800 THB/year", photo: "/images/schools/anglo-singapore-international-school.jpg" },
  { name: "Annabel's Early Years International School", slug: "annabels-early-years-international-school", curricula: ["British"], budget: "under400k", website: "https://www.annabels.ac.th", description: "Annabel's is a British-curriculum early years school in Bangkok, focused specifically on the youngest learners before they move on to primary school elsewhere, joining Tiny Tots, KiddyKare, and IPC among the city's dedicated early years specialists.\n\nAs an early years-only provider, Annabel's core value proposition is a focused, age-appropriate environment for the youngest children, rather than the continuity of a full K-12 pathway that larger schools offer.\n\nFamilies using Annabel's will need to research and select a separate primary school in parallel, since the transition out of Annabel's happens at the end of the early years stage rather than continuing through to primary level on the same campus.\n\nFamilies choosing Annabel's over Bangkok's other early years specialists are typically comparing campus atmosphere, class sizes, and specific location within the broadly similar British early years curriculum framework this category of school shares.", languageOfInstruction: "English", photo: "/images/schools/annabels-early-years-international-school.jpg" },
  { name: "Ascot International School", slug: "ascot-international-school", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://ascot.ac.th", founded: 1995, description: "Ascot is one of the few schools in Bangkok authorized to teach the complete IB continuum: the Primary Years, Middle Years, and Diploma Programmes, plus the Career-related Programme as an additional pathway in the final years for students who want a more vocationally oriented route alongside or instead of the standard Diploma.\n\nFounded in 1995 as Park Place International School before rebranding, Ascot has three decades of local history under its current and former names, giving it a longer track record than many of Bangkok's newer IB-focused schools.\n\nThe school has built a specific niche around football, running an integrated football academy in partnership with coaches from the Thai Premier League, which goes well beyond a typical school PE program and gives serious young players structured, higher level coaching as part of their regular school experience.\n\nFamilies choosing Ascot over NIST or KIS for the full IB continuum are often weighing its specific combination of the Career-related Programme option and football academy partnership against those other schools' different strengths and campus locations.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "331,908 to 594,969 THB/year", photo: "/images/schools/ascot-international-school.jpg" },
  { name: "Associe International Kindergarten Bangkok", slug: "associe-international-kindergarten-bangkok", curricula: ["American", "Japanese", "Thai"], budget: "under400k", website: "https://www.aikb35.ac.th", description: "Associe offers American, Japanese, and Thai curriculum elements side by side, reflecting Bangkok's multicultural family base rather than committing to a single national curriculum framework, a genuinely distinctive trilingual structure among the city's kindergartens.\n\nThat specific American-Japanese-Thai combination sets Associe apart from Bangkok's more common British or American-only early years providers, appealing particularly to Japanese expatriate families alongside Thai and other international families interested in that specific language mix.\n\nAs a kindergarten specifically, Associe functions as an early years starting point, and families will need to plan for a transition to a primary school once children age out, similar to Tiny Tots, IPC, or Kids Academy elsewhere in Bangkok's early years landscape.\n\nFamilies drawn to Associe are typically specifically interested in that trilingual American-Japanese-Thai early years combination, which is not widely replicated elsewhere among Bangkok's kindergarten options.", languageOfInstruction: "English, Japanese, Thai", feeRange: "235,200 to 312,000 THB/year", photo: "/images/schools/associe-international-kindergarten-bangkok.jpg" },
  { name: "Bangkok Christian International School", slug: "bangkok-christian-international-school", curricula: ["American", "Christian"], budget: "under400k", website: "https://www.bcis.ac.th", founded: 1997, description: "BCIS was founded in 1997 by the Korean Missionary Fellowship in Thailand, and follows an American curriculum leading to a US high school diploma, with AP courses available in the upper grades for students pursuing university admission in the US or elsewhere.\n\nThe school is grounded in Christian values, including weekly chapel as part of the regular school schedule, though it explicitly welcomes students of all faiths rather than restricting admission to Christian families, which is a meaningful distinction from schools that require religious affiliation.\n\nGiven its founding through a Korean missionary organization, BCIS has historically drawn a notable portion of its community from Bangkok's Korean expatriate population, alongside the broader international and Thai families the school serves more generally.\n\nFamilies weighing BCIS against Bangkok's other Christian American schools like ICS or Ekamai are typically considering similar things: the specific denominational or organizational background behind each school, campus location, and the balance each strikes between academic and faith components.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Bangkok Grace International School (BGIS)", slug: "bangkok-grace-international-school-bgis", curricula: ["American", "Christian"], budget: "under400k", website: "https://www.grace.ac.th", founded: 1999, description: "BGIS was founded in September 1999 by Rev. Sila Jung, founder of the Thailand Sunday School Institute, beginning with just five kindergarten students before expanding to cover Grades 1 through 6 by 2003, a genuinely grassroots growth story compared to schools that opened at full scale from the start.\n\nThe school remains explicitly Christ-centered, built around the belief that education should ultimately glorify God, giving it a clear and consistently stated faith mission that shapes both curriculum and daily school culture rather than existing as a secondary characteristic.\n\nHaving grown from five students to a full primary school over its first several years, BGIS carries a founder-driven institutional culture similar in spirit to Kevalee International School, another Bangkok school that expanded gradually from a small original core group.\n\nFamilies drawn to BGIS are typically specifically seeking that explicit Christian mission alongside the more personal, founder-driven history behind the school's growth from its very small original beginnings.", languageOfInstruction: "English" },
  { name: "Bangkok Patana School", slug: "bangkok-patana-school", curricula: ["British", "International Baccalaureate"], budget: "over400k", description: "Bangkok Patana is a not-for-profit school run under parent governance rather than private ownership, which shapes a lot of how it operates day to day. Fees go back into the school itself rather than to shareholders, and parents sit on the governing council that oversees major decisions, giving families a genuine stake in how the school is run.\n\nAcademically, Patana follows the English National Curriculum from the early years through to IGCSE, then offers the IB Diploma Programme in the final two years rather than A-Levels, which is a deliberate choice that gives graduates a globally recognized qualification suited to university applications outside the UK as well as within it. With around 2,300 students across roughly 70 nationalities, it is by a wide margin the largest British school in Thailand.\n\nThe campus itself sits on close to 40 acres in the Bang Na area, large enough to house separate primary and secondary sections, extensive sports facilities, and purpose built performing arts and science spaces. That scale supports a wide co-curricular program, from competitive sports through IASAS to music, drama, and Duke of Edinburgh Award participation.\n\nFounded in 1957 in the garden playhouse of Rosamund Stuetzel with just 28 students, Patana has grown into one of the reference points for British international education in Southeast Asia, and its graduates regularly go on to Oxford, Cambridge, and Ivy League universities.", website: "https://www.patana.ac.th", founded: 1957, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "545,000 to 1,044,000 THB/year", photo: "/images/schools/bangkok-patana-school.jpg" },
  { name: "Bangkok Prep", slug: "bangkok-prep", curricula: ["British"], budget: "over400k", website: "https://www.bangkokprep.ac.th", founded: 2003, description: "Bangkok Prep positions itself as a genuinely British curriculum school without the boarding tradition or UK institutional lineage that Harrow or Shrewsbury carry, which tends to make it feel a bit more like a straightforward day school in tone. It follows the English National Curriculum through IGCSE and A-Levels, with Cambridge as the examining body.\n\nThe school has built a reputation around sustainability specifically, becoming the first school in Thailand to earn Eco Schools Green Flag status, the highest level of that international environmental education award. That focus shows up in the day to day curriculum, not just as an occasional theme week.\n\nBangkok Prep is a member of FOBISIA, ISAT, and the regional BISAC and TISAC sporting conferences, giving students access to a fairly full slate of interscholastic sports and academic competition against other British curriculum schools in the region.\n\nCompared to the very largest British schools in the city, Bangkok Prep tends to run smaller, which some families specifically look for as a way to get more individual attention without giving up the British curriculum and IGCSE/A-Level exam pathway.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "384,800 to 862,200 THB/year" },
  { name: "Basis International School Bangkok", slug: "basis-international-school-bangkok", curricula: ["American"], budget: "over400k", website: "https://basis.ac.th", founded: 2019, description: "BASIS Bangkok is the 35th school in the BASIS Curriculum network, a US-based charter school system known specifically for its subject-specialist teaching model, where students work with a different expert teacher for each core subject from an early age rather than a single generalist homeroom teacher. It opened in 2019 next to Central Rama 2.\n\nThe subject-specialist structure is the school's defining academic feature and a genuine point of difference from most other schools in Bangkok, since it means even young students are taught math by a math specialist, science by a science specialist, and so on, rather than one teacher covering all core subjects.\n\nBASIS Curriculum schools are generally regarded as academically rigorous and fast paced, and that reputation for a demanding academic environment is part of what specifically draws families to BASIS Bangkok over some of the city's other American curriculum options.\n\nAs a relatively new campus, having opened in 2019, BASIS Bangkok is still building its local track record, but it benefits from being part of a larger established BASIS network with a defined curriculum model already proven across dozens of other campuses.", ageRange: "Nursery to Grade 12", languageOfInstruction: "English" },
  { name: "Berkeley International School Bangkok", slug: "berkeley-international-school-bangkok", curricula: ["American"], budget: "over400k", website: "https://www.berkeley.ac.th", founded: 2010, description: "Berkeley is a newer American curriculum school, founded in 2010 and earning full WASC accreditation in 2014, with its first graduating class walking in 2017. That relatively recent founding means Berkeley has a shorter track record than Bangkok's oldest American schools like ISB, but it has built its reputation quickly around strong facilities investment.\n\nThe school follows a US-style college preparatory curriculum, and its campus includes both 25 and 50 meter swimming pools along with a full-size grass soccer field, a level of dedicated athletics infrastructure that goes beyond what many similarly sized international schools in Bangkok offer.\n\nBerkeley positions itself as an American curriculum option for families who want a genuinely college-preparatory track without the scale of ISB, appealing specifically to those who prefer a somewhat smaller community while still getting a full US-accredited academic program with AP courses available.\n\nAs a WASC-accredited school with a decade and a half of operating history now, Berkeley has moved past being an unproven newcomer, though it remains smaller in scale and shorter in institutional history than Bangkok's oldest American schools.", ageRange: "Pre-K to Grade 12", languageOfInstruction: "English" },
  { name: "BERNIE British International Prep & Early Years", slug: "bernie-british-international-prep-kindergarten-early-years", curricula: ["British"], budget: "under400k", website: "https://www.bernie-bipc.co.th", description: "BERNIE is a British-curriculum prep and early years school in Bangkok, focused on foundational education before children move into primary school, joining Bangkok's cluster of dedicated early years specialists like Tiny Tots, KiddyKare, and Annabel's.\n\nAs an early years and prep specialist, BERNIE's core offering covers the youngest stage of a child's education, and families will need to plan for a transition to a separate primary school once children complete this early stage.\n\nWithin Bangkok's crowded early years market, schools like BERNIE typically differentiate through campus atmosphere, class sizes, and specific pedagogical approach within the shared British early years curriculum framework.\n\nFamilies researching BERNIE should confirm current facilities, class sizes, and fees directly with the school, as with any of Bangkok's smaller, independently run early years providers.", languageOfInstruction: "English" },
  { name: "Bright Skies International School", slug: "bright-skies-international-school", curricula: ["British"], budget: "under400k", website: "https://brightskiesinternationalschool.com", description: "Bright Skies is a British-curriculum school based in the Ekamai area of Bangkok, part of the city's range of smaller, community-focused international schools operating independently of the larger UK-affiliated networks.\n\nThe central Ekamai location makes Bright Skies convenient for families already living in that popular expat neighborhood, similar to Astra Academy's positioning in the same general area.\n\nAs a smaller, independently run school, Bright Skies likely offers a more intimate community than Bangkok's larger British curriculum schools, though families should confirm specific class sizes and facilities directly.\n\nFamilies drawn to Bright Skies are typically prioritizing that central Ekamai location and a smaller school community over the scale of Bangkok's larger British curriculum options.", languageOfInstruction: "English" },
  { name: "Brighton College Bangkok", slug: "brighton-college-bangkok", curricula: ["British"], budget: "over400k", website: "https://brightoncollege.ac.th", description: "Brighton College Bangkok is part of the Brighton College international network, tied to the original Brighton College in the UK, and like Harrow and Shrewsbury it uses that affiliation to bring UK pastoral structures, house systems, and curriculum planning directly into its Bangkok campus rather than building an independent brand.\n\nThe school follows the English National Curriculum through IGCSE, and has built a particular reputation for its performing arts and academic offerings, positioning itself among the newer wave of UK-affiliated schools that have opened in Bangkok over the past two decades alongside Shrewsbury, Harrow, and Wellington.\n\nAs one of the newer entrants competing directly with Bangkok's established British schools, Brighton College has leaned on its UK affiliation and modern purpose-built facilities to differentiate itself, rather than relying on decades of local history the way Patana or Traill can.\n\nFamilies choosing between Brighton College and its UK-affiliated peers in Bangkok are generally comparing similar things: curriculum consistency with the home UK school, facilities, and location relative to where they live, since the underlying academic offering across this group of schools is broadly similar.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "590,300 to 1,021,800 THB/year", photo: "/images/schools/brighton-college-bangkok.jpg" },
  { name: "British Columbia International School", slug: "british-columbia-international-school", curricula: ["Canadian"], budget: "unknown", website: "https://www.bcisb.ac.th", founded: 2007, description: "BCISB, established in 2007, is the only school in Thailand offering the British Columbia curriculum from Canada, leading to a Canadian Dogwood Diploma alongside Thai high school equivalency, a genuinely distinct academic pathway from the British, American, or IB options most other Bangkok international schools offer.\n\nThe BC curriculum specifically emphasizes inquiry-based, competency-driven learning over traditional exam-only assessment, meaning students are evaluated more on demonstrated skills and project work than through a single set of terminal examinations the way IGCSE or A-Levels are structured.\n\nAs the sole Bangkok provider of this specific Canadian curriculum, BCISB has a genuine niche rather than competing directly against the city's much larger pool of British, American, and IB schools on similar terms.\n\nFamilies specifically seeking a Canadian curriculum pathway, or who have prior BC curriculum experience from Canada itself, are the natural audience for BCISB, distinguishing it clearly from families simply comparing generic international school options.", ageRange: "Ages 3 to 18", languageOfInstruction: "English" },
  { name: "Bromsgrove International School Thailand", slug: "bromsgrove-international-school-thailand", curricula: ["British"], budget: "over400k", website: "https://www.bromsgrove.ac.th", founded: 2002, description: "Bromsgrove Thailand is affiliated with Bromsgrove School in the UK, joining the cluster of UK-linked British schools that have opened in Bangkok over the past two decades. It follows the English National Curriculum through IGCSE and A-Levels, with the direct UK affiliation shaping curriculum planning and pastoral structure the way it does at Harrow, Shrewsbury, and the other UK-linked schools in the city.\n\nFounded in 2002, Bromsgrove is one of the more established schools in this UK-affiliated group, giving it a longer local track record than some of the newer entrants like King's College or Wellington. Its fee positioning tends to run somewhat lower than several of its UK-affiliated peers, which is a genuine differentiator for families comparing this specific group of schools.\n\nAs with its UK-linked peers, Bromsgrove brings house system structure and pastoral care modeled on the UK original into its Bangkok campus, alongside the standard IGCSE and A-Level exam pathway that this whole cluster of schools shares.\n\nFamilies weighing Bromsgrove against Harrow, Shrewsbury, or Brighton College are typically comparing similar academic outcomes and UK-linked pastoral models, with fee level, campus location, and the specific culture of each home UK institution being the more meaningful points of difference.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "259,100 to 680,100 THB/year" },
  { name: "Canadian International School of Thailand", slug: "canadian-international-school-of-thailand", curricula: ["Canadian", "International Baccalaureate"], budget: "under400k", website: "https://canadianschool.com", description: "CIST is situated on a riverside campus in the Pinklao area and evolved from the long-running Thewphaingarm School, giving it institutional roots that predate its current international identity, a transition somewhat similar to how VERSO became Wycombe Abbey, though CIST's evolution happened gradually rather than as a sudden rebrand.\n\nThe school is authorized for the IB Primary Years and Middle Years Programmes, and works toward students earning an Ontario Secondary School Diploma, a specifically Canadian secondary credential that is a genuinely different pathway from the British, American, or standard IB Diploma routes most Bangkok schools offer.\n\nThat combination of IB primary and middle years authorization with an eventual Ontario Diploma outcome is a distinctive structural choice, giving CIST a genuine niche among Bangkok's Canadian curriculum options alongside British Columbia International School, though the two follow different Canadian provincial systems entirely.\n\nFamilies specifically interested in a Canadian secondary credential via the Ontario system, combined with IB-style primary and middle years teaching, are the natural audience for CIST.", languageOfInstruction: "English" },
  { name: "Centurion International School Bangkok", slug: "centurion-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://cisb.ac.th", description: "Centurion is a private British curriculum school in the Suan Luang district, primarily serving early years and primary-age students rather than offering a full K-12 pathway. It keeps a deliberately small community, with students from 14 or more nationalities and typical class sizes around 25.\n\nThat combination of a private, small-scale structure and genuine international diversity within a relatively compact student body is part of Centurion's specific positioning within Bangkok's crowded British curriculum market, most of which is dominated by larger schools.\n\nBecause Centurion focuses primarily on early years and primary ages, families typically need to plan for a transition to a different secondary school once their children age out, similar to how Tiny Tots functions at the even younger end of the age range.\n\nFamilies drawn to Centurion are generally prioritizing that small, genuinely international primary-focused environment in the Suan Luang area over the scale and full K-12 continuity that larger British schools elsewhere in the city offer.", languageOfInstruction: "English" },
  { name: "Charter International School", slug: "charter-international-school", curricula: ["British"], budget: "over400k", website: "https://charter.ac.th", description: "Charter International School was founded by the Thienprasiddhi family, who also run the Plengprasiddhi Kindergarten schools in Thailand, giving Charter a connection to an established local education background even as a standalone international school. It follows the English National Curriculum.\n\nOne distinctive detail about Charter is that its building design was modeled directly on the founding family's own home, with the explicit intention of making the campus feel less institutional and more like an extension of home life for younger students specifically.\n\nAs a family-founded and family-run school rather than part of a larger international group or UK-affiliated network, Charter operates with more independence in how it shapes its specific culture and priorities compared to schools tied into networks like Nord Anglia or the various UK boarding school affiliates in Bangkok.\n\nFamilies drawn to Charter are often specifically looking for that family-run, home-like atmosphere rather than the scale and brand recognition of a larger international network school, making it a genuinely different kind of option within Bangkok's British curriculum landscape.", languageOfInstruction: "English" },
  { name: "Concordian International School Bangkok", slug: "concordian-bangkok-concordian-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.concordian.ac.th", description: "Concordian International School Bangkok offers a curriculum blending international and Chinese-Thai elements, with languages of instruction spanning English, Chinese, and Thai, giving it a genuinely trilingual academic structure similar in spirit to SISB, though built around its own specific program.\n\nThat trilingual English-Chinese-Thai instruction is a distinctive positioning within Bangkok's international school market, appealing specifically to families who want their children fluent across all three languages rather than English with one additional language as most schools offer.\n\nFamilies specifically interested in genuine trilingual education spanning English, Chinese, and Thai would compare Concordian against SISB and Satit Bilingual School of Rangsit University as similarly positioned multilingual options in Bangkok.\n\nFamilies researching Concordian should confirm current curriculum structure, examination pathways, and fees directly with the school for the most up to date details.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Chinese, Thai", feeRange: "646,200 to 993,300 THB/year" },
  { name: "Denla British School", slug: "denla-british-school", curricula: ["British"], budget: "over400k", website: "https://www.dbsbangkok.ac.th", description: "Denla British School is part of the wider Denla Schools group, which has operated in Thailand for several decades under the same founding family, giving DBS specifically a level of institutional backing that some standalone British schools in Bangkok do not have. It follows an Enhanced British Curriculum, meaning the core National Curriculum for England framework with additional elements layered on top.\n\nThe campus sits in Pak Kret, Nonthaburi, putting it further from central Bangkok than many of the city's British schools, which suits families already living in the northern suburbs or willing to trade a longer commute for the school's specific program and larger site.\n\nDBS built its identity around three explicit pillars beyond straightforward academics: entrepreneurship, creative thinking, and wellbeing, and these show up as structured parts of the curriculum rather than occasional add-on activities, which is a deliberate point of difference from more traditionally exam-focused British schools in the city.\n\nBeing part of the broader Denla Schools group also means DBS can draw on shared institutional resources and a longer local track record than a newly founded standalone international school would have, even though the international campus itself is a more recent addition to the group.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "DPREP Bangkok", slug: "dprep-bangkok", curricula: ["International Baccalaureate", "American"], budget: "over400k", website: "https://dprep.ac.th", founded: 2018, description: "D-PREP, originally Didyasarin Preparatory International School, was founded in 2018 by Lady Didyasarin Tavedikul, a member of the family behind the American School of Bangkok's Sukhumvit and Green Valley campuses, giving this newer Bang Na-area school a direct family connection to one of Bangkok's more established American school operators.\n\nThe school combines American curriculum elements with the IB framework, giving families a blended pathway option rather than a purely single-curriculum program, an approach that echoes ASB's own combination of American standards with an IB Diploma option.\n\nAs a relatively new school, having opened in 2018, D-PREP does not yet carry the multi-decade track record of ASB or ISB, but its founding family's background in running American schools in Bangkok gives it institutional experience behind the scenes that a completely independent new school would lack.\n\nFamilies considering D-PREP are often specifically weighing that family connection to the established ASB network against the appeal of a newer, smaller campus in the Bang Na area.", languageOfInstruction: "English" },
  { name: "Ekamai International School", slug: "ekamai-international-school", curricula: ["American", "Adventist"], budget: "under400k", website: "https://www.eis.ac.th", founded: 1946, description: "EIS is operated by the Seventh-day Adventist Mission in Thailand, tracing its roots to 1946 as a church school on Phyathai Road before relocating to its current site in 1957, giving it one of the longer institutional histories among Bangkok's Christian international schools.\n\nThe school follows a US-based curriculum, and has represented students from over 30 nationalities across its history, a genuinely international mix for a school with such specific denominational roots.\n\nAs a Seventh-day Adventist institution specifically, EIS carries a distinct religious identity from the Catholic, generically Christian, or Korean missionary-founded schools elsewhere in Bangkok's faith-based school landscape, which matters for families specifically seeking or avoiding a particular denominational affiliation.\n\nGiven its nearly 80-year history dating back to 1946, EIS has a longer local track record than most of Bangkok's other Christian international schools, most of which were founded considerably more recently in the 1990s or 2000s.", languageOfInstruction: "English" },
  { name: "Garden International School Bangkok", slug: "garden-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.gardenbangkok.com", founded: 1999, description: "Garden International School Bangkok is part of the wider Garden International School group, which also operates campuses in Malaysia, giving it a regional network behind a single Bangkok site rather than being a fully independent standalone school. It was founded in 1999 in the Sathon district.\n\nThe school follows the British National Curriculum from Early Years through to Sixth Form, and deliberately keeps its campus relatively small and close-knit compared to Bangkok's larger British schools like Patana or Harrow, which is a specific selling point for families who want a smaller community over scale.\n\nBeing part of a multi-country group gives Garden some shared institutional resources and curriculum consistency with its Malaysian sister campuses, though the Bangkok site operates with its own local admissions, staff, and day to day culture.\n\nFamilies choosing Garden over Bangkok's larger British schools are typically prioritizing a smaller, more personal school environment, accepting a smaller range of facilities and co-curricular options in exchange for that closer knit community feel.", ageRange: "Early Years to Year 13", languageOfInstruction: "English" },
  { name: "Global English School", slug: "global-english-school", curricula: ["Blended Learning"], budget: "under400k", website: "https://www.facebook.com/gesthailand/", founded: 1980, description: "Global English School, also known as Satit Christian Wittaya, has been run by the Ektrakul family since 1980, maintaining a close-knit, faith-based community alongside its academic program and after-school clubs, giving it over four decades of family-run institutional history.\n\nThat combination of long family ownership and an explicit Christian foundation gives Global English School a distinct identity compared to more recently founded or corporately owned schools, with a level of institutional continuity under a single family that few Bangkok schools can match.\n\nAs a smaller, faith-based school under continuous family leadership since 1980, Global English School likely offers a genuinely personal, community-oriented experience distinct from Bangkok's larger, more corporately structured international schools.\n\nFamilies drawn to Global English School are typically seeking that specific combination of long-standing family ownership and Christian community values, alongside its academic program.", languageOfInstruction: "English" },
  { name: "Global Indian International School", slug: "global-indian-international-school", curricula: ["Indian"], budget: "under400k", website: "http://www.gisschool.org", description: "This Bangkok campus is part of the wider Global Indian International School network, located in Pathum Thani rather than central Bangkok, and specifically serves the city's Indian community alongside local and other international families interested in the school's specific curriculum approach.\n\nBeing part of a larger international network gives this campus access to shared curriculum resources and institutional consistency with GIIS campuses in other countries, which matters for families who may relocate between GIIS locations internationally.\n\nThe Pathum Thani location places it outside the central Bangkok cluster of international schools, which suits families already based in that area or specifically seeking out this particular school's program regardless of commute distance.\n\nFamilies choosing GIIS Bangkok are typically doing so specifically because of its connection to India-focused curriculum elements and the wider GIIS network, rather than comparing it directly against Bangkok's British or American mainstream international schools.", languageOfInstruction: "English" },
  { name: "Glory Singapore International School", slug: "glory-singapore-international-school", curricula: ["British", "Singaporean"], budget: "under400k", website: "https://glorysingapore.com", description: "Glory Singapore International School is a smaller Bangkok school combining British and Singaporean curriculum elements, with a lower public profile than the city's larger Singapore-curriculum providers like SISB.\n\nAs a smaller, less internationally networked school than SISB's multi-campus operation, Glory Singapore likely offers a more locally focused, intimate version of a Singapore-influenced curriculum blended with British elements.\n\nDetailed public information on Glory Singapore's specific facilities, fees, and track record is limited compared to Bangkok's larger international schools, so families interested should plan on contacting the school directly for current details.\n\nFamilies specifically interested in a British-Singaporean curriculum blend, but who want a smaller school than the larger SISB network, would consider Glory Singapore alongside Thai-Singapore International School as similarly positioned options.", languageOfInstruction: "English" },
  { name: "Hampton International School", slug: "hampton-international-school", curricula: ["British"], budget: "over400k", website: "https://hamptonschool.ac.th", founded: 2009, description: "Hampton is a family-owned early years school with campuses in Chaengwattana and Sathorn, teaching a British curriculum with Reggio Emilia-inspired methods specifically for children aged 18 months to 6 years, making it an early years specialist rather than a full K-12 school.\n\nFounded in 2009, Hampton has been recognized by Thailand's Ministry of Social Development and Human Security for early years education quality, an external validation that goes beyond the standard accreditation most international schools cite.\n\nThe Reggio Emilia approach specifically emphasizes child-led, exploratory learning over structured instruction, which is a meaningfully different pedagogical philosophy from the more traditional British curriculum delivery at most other early years providers in Bangkok.\n\nAs with other early years specialists like Tiny Tots or KiddyKare, families using Hampton will need to plan for a transition to a separate primary school once their child ages out at 6, making the choice of a Hampton-compatible next school worth considering early.", ageRange: "18 months to 6 years", languageOfInstruction: "English" },
  { name: "Harrow International School Bangkok", slug: "harrow-international-school-bangkok", curricula: ["British"], budget: "over400k", description: "Harrow Bangkok is part of the Harrow International network, tied to the original Harrow School in the UK, and it leans into that heritage more visibly than most Bangkok international schools, with a house system, uniforms, and traditions modeled directly on the English boarding school original.\n\nThe school follows the English National Curriculum through IGCSE and A-Levels, and offers boarding as an option alongside day places, which is relatively unusual among Bangkok's international schools and appeals to families who want the option even if they do not use it immediately.\n\nHarrow's campus includes the kind of large-scale sports and performing arts facilities that come with the Harrow brand internationally, and the school competes actively in Bangkok's interscholastic sports conference alongside the city's other major British and American schools.\n\nAs with Shrewsbury, Harrow gives Bangkok families a way to access a genuinely UK-linked educational brand without leaving Thailand, which is part of its specific appeal versus schools that are British in curriculum only rather than in institutional lineage.", website: "https://www.harrowschool.ac.th", founded: 1998, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "634,600 to 1,063,000 THB/year" },
  { name: "Heathfield International School", slug: "heathfield-international-school", curricula: ["British"], budget: "over400k", website: "https://heathfield.ac.th", founded: 2007, description: "Heathfield formed in 2007 from the former Lord Shaftesbury International School, in partnership with Heathfield School in Kidderminster, UK, giving it a UK institutional link similar in structure to Harrow or Shrewsbury, though on a considerably smaller scale. It follows the English National Curriculum through IGCSE and A-Levels.\n\nThe school sits in the Saphan Sung area, away from the more concentrated cluster of international schools in central Sukhumvit, and deliberately keeps its community small, positioning itself as a genuinely community-focused option rather than competing on scale with Bangkok's larger British schools.\n\nBecause Heathfield formed out of an existing school's transition rather than opening fresh, it carries some institutional continuity predating its current UK partnership, even though the Heathfield-branded identity itself dates to 2007.\n\nFamilies drawn to Heathfield are generally prioritizing a small, tight-knit school community and a UK curriculum link, similar in spirit to Garden International School, over the scale, facilities, and brand recognition that Bangkok's larger UK-affiliated schools offer.", ageRange: "Nursery to Year 12", languageOfInstruction: "English" },
  { name: "International Community School", slug: "international-community-school", curricula: ["American", "Christian"], budget: "over400k", website: "https://www.ics.ac.th", founded: 1993, description: "ICS was founded in 1993 by a coalition of expatriate families and Christian school networks, opening with 120 students in the Sathorn area before relocating to its current Bang Na site as the school grew. It is explicitly Christ-centered in its mission, with faith woven into daily school life rather than treated as a separate program.\n\nThe school holds both WASC and ACSI accreditation, the latter being specific to Christian schools internationally, which signals a genuine dual commitment to both academic rigor and its faith-based identity rather than treating one as secondary to the other.\n\nICS has also expanded beyond Bangkok, operating a second campus in Udon Thani, which is relatively unusual among the city's international schools and reflects demand for a similar faith-based American curriculum option outside the capital.\n\nFamilies specifically seeking a Christian, American curriculum school in Bangkok, rather than a secular one, tend to compare ICS against Bangkok Christian International and Ekamai, the city's other explicitly faith-based American options.", ageRange: "Ages 4 to 18", languageOfInstruction: "English" },
  { name: "International Montessori Center", slug: "international-montessori-center", curricula: ["British", "Montessori"], budget: "under400k", website: "https://www.imc.ac.th", description: "International Montessori Center is a British-curriculum school built around Montessori teaching methods, offering child-led learning within a structured academic framework, joining Montessori Academy Bangkok among the city's Montessori-method providers.\n\nThe Montessori approach specifically emphasizes hands-on learning materials, mixed-age classrooms, and self-paced progression, a meaningfully different pedagogical philosophy from the more conventional grade-by-grade instruction most Bangkok schools use.\n\nFamilies specifically seeking Montessori methodology within a British rather than American curriculum framework would consider International Montessori Center over Montessori Academy Bangkok, which follows an American base instead.\n\nFamilies interested should confirm current age ranges served and how far through a child's education the school carries the Montessori approach, since these programs vary in scope.", languageOfInstruction: "English" },
  { name: "International Pioneers School", slug: "international-pioneers-school", curricula: ["British"], budget: "under400k", website: "https://ips.ac.th", founded: 1998, description: "IPS has operated under the explicit tagline Quality Affordable Education since 1998, positioning itself deliberately as a lower-cost alternative within Bangkok's British curriculum landscape rather than competing on premium facilities or brand name. It follows a British curriculum through IGCSE and A-Levels.\n\nThe school operates across multiple Bangkok campuses, including sites in Krungthonburi and Bangkhae, giving it a wider geographic footprint than most single-site international schools in the city, which is part of how it manages to keep fees more accessible while still offering full IGCSE and A-Level pathways.\n\nThat multi-campus structure means families researching IPS should confirm which specific campus they are looking at, since facilities, exact fees, and even year group availability can vary between sites within the same overall school.\n\nFamilies drawn to IPS are typically prioritizing genuine affordability within a proper British IGCSE and A-Level framework, rather than the premium positioning of schools like Patana or the UK-affiliated boarding schools elsewhere in the city.", languageOfInstruction: "English" },
  { name: "IPC International Kindergarten", slug: "ipc-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.ipcthai.com", founded: 1983, description: "IPC, formally the International Pre-School Centre, was founded in 1983 by Khun Marianne Chirathivat and family, making it one of Bangkok's oldest dedicated preschools, predating most of the city's current wave of international kindergartens by well over a decade.\n\nThe Chirathivat family name carries significant local business recognition in Thailand, and IPC's founding by a member of that family reflects a broader pattern of established Thai families investing early in international-standard early childhood education for the local and expatriate community.\n\nAs a preschool specifically focused on early childhood education for young children, rather than a full K-12 institution, IPC functions as a starting point that families move on from, similar to Tiny Tots, once children reach primary school age.\n\nWith over four decades of operating history, IPC has a longer track record than nearly all of Bangkok's other dedicated international preschools, most of which opened considerably more recently.", languageOfInstruction: "English" },
  { name: "Kevalee International School", slug: "kevalee-international-school", curricula: ["American"], budget: "under400k", website: "https://www.kevalee.ac.th", founded: 1996, description: "Kevalee began in 1996 as a home-based kindergarten run by Mrs. Juliana, an educator who already had more than 40 years of experience at international schools in Bangkok before founding her own. That personal, experience-driven origin sets it apart from schools founded as corporate or institutional ventures from the start.\n\nThe school expanded significantly in 2006, growing from its original kindergarten focus to cover the full range from Grade 1 through Grade 12, moving to a purpose-built campus in the Klong Samwa district to accommodate that growth.\n\nHaving grown organically from a single founder's home-based kindergarten into a full K-12 school over three decades, Kevalee carries a more personal, founder-driven institutional culture than schools that opened at full scale from day one.\n\nFamilies drawn to Kevalee are often specifically interested in that founder-led history and the sense of continuity it brings, alongside the practical benefit of a full K-12 pathway on one campus in the Klong Samwa area.", languageOfInstruction: "English" },
  { name: "KiddyKare International Kindergarten", slug: "kiddykare-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.kiddykare.ac.th", description: "KiddyKare is a British curriculum kindergarten serving families in Bangkok's early years and pre-primary age range, part of the city's long-established network of small international preschools that families use before transitioning to a primary school.\n\nAs a kindergarten-only provider, KiddyKare's core offering is the youngest end of the international school system, and families typically research and select a separate primary school in parallel, since KiddyKare itself does not carry students through to primary or secondary levels.\n\nOperating within Bangkok's crowded early years market means schools like KiddyKare typically differentiate through campus atmosphere, class sizes, and specific pedagogical approach within the shared British curriculum foundation, rather than through exam results or secondary school outcomes, since those come later at a different school entirely.\n\nFamilies researching KiddyKare are generally comparing it against Bangkok's other standalone kindergartens like Tiny Tots, IPC, or The First Steps, weighing location, atmosphere, and specific program details among otherwise broadly similar early years options.", languageOfInstruction: "English" },
  { name: "KIS International School Bangkok", slug: "kis-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.kis.ac.th", description: "KIS is one of the smaller full-continuum IB schools in Bangkok, deliberately built around a more intimate community than the city's largest IB providers like NIST. It teaches the Primary Years, Middle Years, and Diploma Programmes as one continuous IB pathway from age 3 through to graduation.\n\nThe campus sits close to the city center near Huai Khwang, which keeps it within easier reach of central Bangkok neighborhoods compared to some of the larger suburban campuses further from downtown. That central location is part of the appeal for families who prioritize commute time.\n\nDespite its smaller size relative to NIST or ISB, KIS has built a strong reputation specifically for its IB Diploma exam results, and the school leans into its smaller scale as a selling point, arguing that a tighter knit community allows for more individual attention across the full IB continuum.\n\nFamilies choosing KIS over Bangkok's larger IB providers are typically prioritizing community size and location over the scale of facilities and co-curricular breadth that a bigger campus like NIST or ISB can offer.", ageRange: "Ages 3 to 19", languageOfInstruction: "English", feeRange: "459,800 to 984,700 THB/year", photo: "/images/schools/kis-international-school-bangkok.jpg" },
  { name: "KPIS International School", slug: "kpis-international-school", curricula: ["American"], budget: "unknown", website: "https://kpis.ac.th", founded: 2005, description: "KPIS is a privately owned, family-established school in the Ramintra area of northern Bangkok, following a US-based curriculum. It has held full WASC accreditation since 2009, giving it a formally recognized US-standard academic program despite being a smaller, independently run school rather than part of a larger international group.\n\nBeing family-owned rather than corporately run or tied to a UK or international school network gives KPIS more independence in shaping its specific culture and priorities, similar in structure to Charter International School, though with an American rather than British curriculum base.\n\nThe Ramintra location places KPIS further from the central Sukhumvit cluster of international schools, which suits families already based in northern Bangkok or those specifically prioritizing that part of the city over a shorter commute to downtown.\n\nFounded in 2005, KPIS has built a two-decade track record as a smaller, independently owned American curriculum option, appealing to families who want WASC-level accreditation without the scale of Bangkok's largest American schools like ISB.", ageRange: "Nursery to Grade 12", languageOfInstruction: "English" },
  { name: "MYIS International School", slug: "magic-years-international-school-thailand", curricula: ["International Baccalaureate", "American"], budget: "over400k", website: "https://magicyears.ac.th", founded: 1990, description: "MYIS, founded in 1990 near the Nichada Thani expatriate community in Nonthaburi, is one of only a handful of Bangkok-area schools offering both the IB Primary Years and Middle Years Programmes, with plans to add the Diploma Programme by 2027.\n\nThe small, family-centered campus includes a saltwater pool, science labs, and a small farm, reflecting a deliberately intimate, hands-on approach to education rather than competing on the scale of nearby ISB.\n\nBeing located near Nichada Thani places MYIS in the same general area as ISB, giving Nonthaburi-based families a smaller, more community-focused IB alternative without needing to commute into central Bangkok.\n\nFamilies drawn to MYIS are typically prioritizing that small, family-centered IB environment over the scale of ISB, while still wanting access to the same general Nonthaburi location.", ageRange: "Ages 1 to 16", languageOfInstruction: "English" },
  { name: "NIST International School Bangkok", slug: "nist-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", description: "NIST holds a specific distinction among Bangkok's IB schools: it was the first school in Thailand authorized to teach the complete IB continuum, the Primary Years, Middle Years, and Diploma Programmes, as one continuous framework rather than adding the Diploma onto a different curriculum base in the final years. That matters for families who want IB-style inquiry based learning from the very start of a child's education, not just at the end.\n\nThe school was founded in 1992 with backing from Bangkok's United Nations community, and that international, mission-driven origin still shows in its makeup. NIST is run as a not-for-profit under a parent-elected board, and its student body is unusually diverse even by Bangkok international school standards, with no single nationality dominating enrollment.\n\nThe central Sukhumvit campus puts NIST within easy reach of the Sukhumvit corridor neighborhoods where many expat families already live, which is part of why it is a popular choice for families prioritizing a shorter commute over a larger suburban campus. Facilities include dedicated primary and secondary buildings, science and design technology labs, and strong arts and athletics programs.\n\nNIST is consistently regarded as one of the strongest IB Diploma results performers in Bangkok, and it competes in IASAS alongside ISB, Patana, and other top regional schools, giving students a fairly serious level of interscholastic sports and arts competition to take part in.", website: "https://www.nist.ac.th", founded: 1992, ageRange: "Ages 3 to 18", languageOfInstruction: "English", feeRange: "650,200 to 1,132,800 THB/year", photo: "/images/schools/nist-international-school-bangkok.jpg" },
  { name: "The American School of Bangkok (ASB)", slug: "the-american-school-of-bangkok-asb", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://asb.ac.th", founded: 1983, description: "ASB opened in 1983 and is one of Bangkok's longer running American schools, now operating two distinct campuses. The original Sukhumvit site was rebranded XCL American School of Bangkok in 2022 under new ownership by XCL Education, while the Green Valley campus, established in 1997, remains under the ASB name.\n\nGreen Valley offers both day and boarding options, which is relatively unusual among Bangkok's American curriculum schools, and follows Common Core standards with AP courses and an IB Diploma pathway available in the final two years.\n\nBecause the Sukhumvit campus now operates under separate XCL ownership and branding, families researching this school should be careful to confirm which specific campus, and therefore which ownership and curriculum details, they are actually looking at, since the ASB and XCL names now represent genuinely different operating entities despite the shared history.\n\nWith over four decades of combined history across its campuses, ASB carries one of the longer track records among Bangkok's American schools, alongside ISB and Ruamrudee.", languageOfInstruction: "English", photo: "/images/schools/the-american-school-of-bangkok-asb.jpg" },
  { name: "The British School of Bangkok (Topsy Turvy)", slug: "the-british-school-of-bangkok-topsy-turvy-international-school", curricula: ["British"], budget: "under400k", website: "https://bsbangkok.ac", description: "The British School of Bangkok, also known as Topsy Turvy International School, is a British-curriculum early years and primary school, part of the city's network of smaller National Curriculum for England providers.\n\nAs a primary-focused school, families using this school will need to plan for a secondary school transition once children progress beyond primary level, similar to several of Bangkok's other primary-only British curriculum providers.\n\nThe dual naming, operating under both a formal and a more distinctive Topsy Turvy branding, is worth noting for families researching the school, since both names refer to the same institution.\n\nFamilies interested should confirm current curriculum structure, class sizes, and fees directly with the school for the most up to date details.", languageOfInstruction: "English" },
  { name: "The Country School by ELC", slug: "the-country-school-by-elc", curricula: ["British"], budget: "under400k", website: "https://www.elc.ac.th", description: "The Country School is part of the ELC, or Early Learning Centre, family of schools in Bangkok, offering a British-curriculum, nature-oriented early education setting distinct from more traditional classroom-based kindergartens.\n\nThat nature-oriented approach, reflected in the Country School name itself, suggests an emphasis on outdoor and hands-on learning experiences alongside standard early years academics, a specific pedagogical choice within the ELC network's broader offerings.\n\nBeing part of the ELC family, alongside sister schools The Purple Elephant 55 and The Tiny Seeds, means families can potentially compare several related early years options within the same network before choosing the specific site and approach that fits best.\n\nFamilies drawn to The Country School are typically interested in that nature-oriented, outdoor-focused early years approach specifically, within the broader ELC network of Bangkok early education providers.", languageOfInstruction: "English" },
  { name: "The First Steps International School", slug: "the-first-steps-international-school", curricula: ["British"], budget: "under400k", website: "https://thefirststeps.ac.th", description: "The First Steps is a British curriculum early years and pre-school program in Bangkok, part of the city's established network of smaller international kindergartens that serve local and expat families before children move on to a primary school.\n\nAs an early years specialist rather than a full K-12 school, The First Steps functions similarly to KiddyKare, Tiny Tots, and IPC within Bangkok's early education landscape, with families typically planning ahead for which primary school their child will transition to once they age out of the early years program.\n\nWithin this crowded segment of Bangkok's international school market, schools like The First Steps generally differentiate on campus atmosphere, class sizes, and specific teaching approach, since the underlying British early years curriculum framework is broadly shared across this category of school.\n\nFamilies choosing The First Steps are typically weighing it against Bangkok's other standalone early years providers on location, atmosphere, and fit for their specific child, rather than on exam outcomes or secondary pathways, which come later at a different school.", languageOfInstruction: "English" },
  { name: "The Purple Elephant 55", slug: "the-purple-elephant-55", curricula: ["English Program"], budget: "under400k", website: "https://www.elc.ac.th", description: "The Purple Elephant is part of the ELC family of schools in Bangkok, offering an English Program environment for younger learners, joining The Country School and The Tiny Seeds as sister campuses within the same early years network.\n\nBeing part of a multi-site network gives The Purple Elephant shared institutional resources and curriculum consistency with its ELC sister schools, even as each individual site maintains its own specific campus and community.\n\nAs an early years specialist, The Purple Elephant functions as a starting point rather than a full K-12 school, meaning families will need to plan for a primary school transition once children complete the early years stage.\n\nFamilies researching The Purple Elephant may also want to compare it against its ELC sister schools, The Country School and The Tiny Seeds, since each site within the network may offer a slightly different specific approach or location.", languageOfInstruction: "English" },
  { name: "The Tiny Seeds International Pre-School", slug: "the-tiny-seeds-international-pre-school-bangkok", curricula: ["English Program"], budget: "under400k", website: "https://www.elc.ac.th", description: "The Tiny Seeds is part of the ELC family of schools in Bangkok, offering an English Program pre-school setting for the city's youngest learners, joining The Country School and The Purple Elephant as sister campuses within the same early years network.\n\nAs with its ELC sister schools, The Tiny Seeds benefits from shared institutional resources and curriculum consistency across the network, while maintaining its own specific campus community and location.\n\nBeing a pre-school specifically, The Tiny Seeds serves the very youngest stage of a child's education, with families planning ahead for the transition to a primary school once children age out of the pre-school program.\n\nFamilies researching The Tiny Seeds may want to compare it against its ELC sister schools, The Country School and The Purple Elephant, to find the specific location and approach that best fits their family.", languageOfInstruction: "English" },
  { name: "The Village International Education Centre (VIE)", slug: "the-village-international-education-centre-vie", curricula: ["British"], budget: "over400k", website: "https://www.village-education.com", description: "VIE is a British-curriculum school dedicated specifically to children with special educational needs, with over 16 years of experience serving Bangkok families whose children need more individualized support than a mainstream international school typically provides.\n\nVIE's staff includes speech, language, and occupational therapists alongside academic teachers, integrating therapeutic support directly into the school day rather than treating it as a separate outside service families need to arrange independently.\n\nEvery student at VIE has an Individual Educational Plan built around their specific needs, reflecting a genuinely individualized approach rather than a standard curriculum applied uniformly across all students.\n\nAlongside New Day Learning, VIE is one of Bangkok's dedicated special educational needs schools, giving families seeking this kind of specialized, therapeutically integrated education a proper option rather than relying solely on learning support services layered onto a mainstream school.", languageOfInstruction: "English" },
  { name: "Thonglor Greenfield Nursery", slug: "thonglor-greenfield-nursery", curricula: ["British"], budget: "under400k", website: "https://www.thonglorgreenfieldnursery.com", description: "Thonglor Greenfield Nursery is a British-curriculum nursery in the Thonglor area of Bangkok, serving families with young children in one of the city's most central and popular expat neighborhoods.\n\nThe Thonglor location places this nursery in easy reach of the many expat families already based in that specific corridor of central Bangkok, similar to how Bright Skies and Astra Academy serve the nearby Ekamai area.\n\nAs a nursery specifically, Thonglor Greenfield serves the very earliest stage of a child's education, with families planning ahead for a kindergarten and eventually primary school transition as their child grows.\n\nFamilies drawn to Thonglor Greenfield are typically prioritizing that central, convenient Thonglor location for their youngest child's very first school experience.", languageOfInstruction: "English" },
  { name: "Tiny Tots International School", slug: "tiny-tots-international-school", curricula: ["British", "Indian"], budget: "under400k", website: "https://tinytotsinternational.com", description: "Tiny Tots is a central Bangkok preschool and kindergarten built around a deliberately cosmopolitan, small-community atmosphere rather than aiming for scale. It serves children from age 1, making it one of the earlier entry-point options among Bangkok's international early years providers.\n\nBeyond its regular weekday program, Tiny Tots also runs a Saturday playgroup, giving families a lower-commitment way to introduce very young children to the school's environment before committing to full-time enrollment, or as a supplementary option for families using a different primary school.\n\nAs a preschool and kindergarten specifically, rather than a K-12 school, Tiny Tots is a starting point that families typically move on from after the early years, making the transition to a primary school elsewhere a normal part of the Tiny Tots experience rather than an exception.\n\nFamilies choosing Tiny Tots are usually prioritizing that specifically cosmopolitan, small-scale early years environment and central Bangkok location for the youngest end of their child's education.", languageOfInstruction: "English" },
  { name: "Traill International School", slug: "traill-international-school", curricula: ["British"], budget: "over400k", website: "https://www.traillschool.ac.th", founded: 1966, description: "Traill holds a specific place in Bangkok's international school history: founded in 1966 by Mr and Mrs Anthony Traill, it was the first British secondary school established in Thailand, opening with just 82 students. Nearly 60 years later, it remains on its original Bang Kapi campus.\n\nThe school follows a British curriculum through IGCSE and A-Levels, and that nearly six-decade history gives it a longer local track record than almost any other British school in the city aside from Bangkok Patana, which was founded around the same era.\n\nDespite that long history, Traill has stayed on its original site rather than expanding into a larger multi-campus operation the way some of the newer UK-affiliated schools have, which keeps it feeling more like a single established community school than a branch of a larger international network.\n\nFamilies drawn to Traill are often specifically interested in that combination of genuine local history and a straightforward, focused British curriculum, rather than the UK institutional branding that Harrow, Shrewsbury, or Wellington bring to their Bangkok campuses.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Trinity International School", slug: "trinity-international-school", curricula: ["American", "Adventist"], budget: "under400k", website: "https://trinity.ac.th", description: "Trinity is a Christian, student-centered school licensed by Thailand's Ministry of Education and a member of the International Schools Association of Thailand, positioning it within the country's broader network of ISAT-affiliated international schools rather than operating in isolation.\n\nThe school combines academic study with a stated focus on character development, meaning its program is built around more than just exam results, with explicit attention to values and personal growth as part of the regular curriculum rather than a separate co-curricular track.\n\nAs a Christian school, Trinity shares some similarities in mission with ICS, Bangkok Christian International, and Ekamai, though each of these faith-based schools has its own specific denominational background, campus culture, and curriculum details that families researching this category of school should compare individually.\n\nFamilies drawn to Trinity are generally specifically seeking that combination of Ministry of Education licensing, ISAT membership, and an explicit character-development focus alongside standard academics.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Verso International School", slug: "verso-international-school", curricula: ["American"], budget: "over400k", description: "VERSO International School closed in 2026. Its campus near Suvarnabhumi Airport has reopened as Wycombe Abbey International School Bangkok, listed separately in this directory." },
  { name: "Wellington International School Bangkok", slug: "wellington-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.wellingtoncollege.ac.th", founded: 2018, description: "Wellington Bangkok is affiliated with Wellington College in the UK, joining Harrow, Shrewsbury, and Brighton College as part of a cluster of UK-linked British schools that have opened in Bangkok since the early 2000s, each bringing a version of their home institution's pastoral system and house structure into a Thai campus.\n\nThe school follows the English National Curriculum through to IGCSE and A-Levels, and places a specific emphasis on wellbeing as a stated part of its educational philosophy, which is a hallmark Wellington College brings across its international network, not just a Bangkok-specific initiative.\n\nAs one of the more recently established UK-affiliated schools in the city, Wellington has built modern, purpose-designed facilities from the outset rather than expanding an older campus incrementally, which shows in its sports and arts spaces.\n\nFamilies weighing Wellington against Bangkok's other UK-affiliated schools are typically comparing similar academic outcomes, since all follow the same underlying English curriculum and exam boards, with the real differences coming down to campus location, facilities, and the specific culture each home UK institution brings to its house system.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "615,250 to 1,240,137 THB/year" },
  { name: "Shrewsbury International School Bangkok", slug: "shrewsbury-international-school-bangkok", curricula: ["British"], budget: "over400k", description: "Shrewsbury Bangkok carries a genuine, direct affiliation with the 500 year old Shrewsbury School in the UK, rather than just borrowing the name, which means its curriculum, pastoral structure, and house system are modeled closely on the original English boarding school rather than built from scratch for the Bangkok market.\n\nThe school operates two campuses, a riverside site and a second City Campus in Huai Khwang, giving it more flexibility on location than most single-campus Bangkok schools. Families choosing between the two generally weigh commute against campus facilities, since the original riverside site has more space for sports and outdoor activities.\n\nAcademically, Shrewsbury follows the English National Curriculum through IGCSE, then A-Levels rather than the IB, which is a meaningful distinction from several of its British-curriculum peers in the city. It has built a reputation as one of the more academically competitive British schools in Bangkok, with strong university placement outcomes.\n\nFounded in 2003, Shrewsbury is younger than Patana or ISB, but has grown quickly on the strength of its UK affiliation and has become one of the established names families compare against Patana when weighing British curriculum options in the city.", website: "https://www.shrewsbury.ac.th", founded: 2003, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "691,800 to 1,208,400 THB/year" },
  { name: "International School Bangkok (ISB)", slug: "international-school-bangkok-isb", curricula: ["American", "International Baccalaureate"], budget: "over400k", description: "ISB holds the distinction of being Thailand's first international school, opening in 1951 as the International Children's Center on the grounds of the US Embassy, serving an initial group of just 50 children from UN and embassy families. That history helps explain why the school still carries an unusually international, diplomatic-community feel even today.\n\nThe campus occupies roughly 37 acres inside Nichada Thani, a gated residential community in Nonthaburi built specifically around the school. Many ISB families choose to live inside or near Nichada Thani itself, since it removes the cross-town commute that affects families at more centrally located schools, at the cost of being further from downtown Bangkok on weekends.\n\nAcademically, ISB runs an American curriculum through Advanced Placement courses, with the IB Diploma Programme also available as an option in the final two years, giving families a choice between the two most internationally recognized university pathways. ISB was the first school in Thailand to offer the IB Diploma at all, alongside its American track.\n\nWith around 1,900 students, ISB is large enough to field a full IASAS athletics and arts program, and its extensive campus includes facilities that go well beyond a typical school day, more in line with a small American high school and college campus combined.", website: "https://www.isb.ac.th", founded: 1951, ageRange: "Ages 3 to 18", languageOfInstruction: "English", feeRange: "681,000 to 1,219,000 THB/year" },
  { name: "Ruamrudee International School (RIS)", slug: "ruamrudee-international-school-ris", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://www.rism.ac.th", founded: 1957, description: "Ruamrudee, almost always referred to as RIS, is one of Bangkok's oldest American curriculum schools, founded the same year as Bangkok Patana in 1957, and has grown into one of the largest international schools in the city by enrollment. It offers a genuinely broad range of pathways, including an American diploma track, AP courses, and the IB Diploma Programme as an option in the final two years.\n\nThe main campus is large enough to support both a full American-style athletics and activities program and a separate Swiss Section teaching a German-language curriculum for German-speaking families, an unusual combination that reflects how large and diverse the school's population has become over nearly seven decades.\n\nRIS is a member of IASAS, competing directly against ISB, Patana, NIST, and other major regional schools in sports and arts, which places it firmly among Bangkok's tier of large, well-resourced international schools rather than the city's smaller boutique options.\n\nWith such long history and scale, RIS tends to appeal to families who want an established, full-service American school with genuine choice in exam pathway, rather than a smaller or more specialized option.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "548,400 to 1,527,000 THB/year" },
  { name: "King's College International School Bangkok", slug: "kings-college-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.kingsbangkok.ac.th", founded: 2020, description: "King's College Bangkok is affiliated with King's College School in Wimbledon, UK, joining the cluster of UK-linked British schools that have opened in Bangkok over the past two decades alongside Harrow, Shrewsbury, Brighton College, and Wellington. It follows the English National Curriculum through IGCSE and A-Levels.\n\nOpened in 2020, King's College Bangkok is one of the newest of these UK-affiliated schools in the city, which means its facilities were purpose designed from the outset rather than expanded incrementally from an older site, though it also means the school has a shorter local track record than its more established peers.\n\nAs with the other UK-affiliated schools in Bangkok, King's leans on its direct institutional link to the UK original for curriculum planning, teacher training, and pastoral structure, giving Bangkok families a way to access that specific UK school's approach without leaving Thailand.\n\nFamilies comparing King's College against Bangkok's other recently opened UK-affiliated schools are typically weighing similar factors: campus location, facilities, and which UK institution's specific culture and house system appeals to them, since the underlying English curriculum is broadly consistent across this group of schools.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "616,000 to 1,063,000 THB/year" },
    { name: "St Andrews International School Bangkok", slug: "st-andrews-international-school-bangkok", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://www.nordangliaeducation.com/sta-bangkok", founded: 1997, description: "This is the original St Andrews campus in Bangkok, located in the Vadhana district and owned by Nord Anglia Education, a major international schools group that also owns schools across Asia, Europe, and the Americas. It is a separate operation from the unrelated Cognita-owned St Andrews campuses at Sathorn, Sukhumvit 107, and Dusit, despite the shared name.\n\nFounded in 1997, the school offers a British-style education from Foundation Stage age 2 through to age 18, and being part of the Nord Anglia network gives it access to shared curriculum resources and partnerships across that group's other schools worldwide, including collaborations with organizations like MIT and Juilliard that Nord Anglia arranges centrally.\n\nThe school has picked up IB and international school awards recognition in past years, and being commonly known by the abbreviation STA71, referencing its location on Sukhumvit Soi 71, helps distinguish it locally from the other St Andrews branded campuses in the city that operate under entirely different ownership.\n\nFamilies should be careful not to confuse this school with the Cognita-run St Andrews campuses elsewhere in Bangkok. Despite the identical branding, they are unrelated schools under separate ownership groups with their own curricula and admissions.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "400,700 to 873,800 THB/year", photo: "/images/schools/st-andrews-international-school-bangkok.jpg" },
  { name: "Wells International School", slug: "wells-international-school", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://wells.ac.th", founded: 1999, description: "Wells was founded in 1999 and has grown to four campuses across Bangkok plus one in Chonburi, giving it a wider geographic footprint than most single-site American curriculum schools in the city. It follows a combined American and IB curriculum.\n\nThe school is known for relatively small average class sizes, around 16 students, and a close student-to-teacher ratio, which is a specific selling point against larger American schools like ISB that offer more scale but less individual attention per student.\n\nWith five campuses total, families researching Wells need to confirm which specific location they are considering, since facilities and exact program details can vary between sites, similar to the multi-campus structure at International Pioneers School.\n\nFamilies drawn to Wells are typically prioritizing that combination of American plus IB curriculum choice with smaller class sizes, over the scale of Bangkok's largest American schools.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Regent's International School Bangkok", slug: "regents-international-school-bangkok", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://regents.ac.th", description: "Regent's International School Bangkok teaches the English National Curriculum from Early Years through IGCSE, then offers the IB Diploma Programme in the Sixth Form rather than A-Levels, a similar structural choice to Bangkok Patana. That combination of British curriculum through IGCSE with an IB finish is less common among Bangkok's British schools, most of which stick with A-Levels straight through.\n\nThe school is a member of the Round Square Association, an international network of schools built around service, adventure, and experiential learning alongside academics, which shapes its co-curricular program more than pure exam preparation does at some other British schools in the city.\n\nRegent's has also built specific outside partnerships into its program, including a Premier League football academy collaboration and a partnership with Yamaha Music School, giving students structured access to specialist coaching in sport and music beyond what an in-house PE or music department would typically offer.\n\nAs one of Bangkok's longer established British schools, Regent's competes for families alongside Patana and the city's other major British curriculum options, with its Round Square membership and specific external partnerships forming part of what differentiates it from its peers.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Amnuay Silpa School", slug: "amnuay-silpa-school", curricula: ["British", "Thai"], budget: "over400k", website: "https://www.amnuaysilpa.ac.th", founded: 1926, description: "Amnuay Silpa runs a genuinely dual curriculum rather than an English-medium school with Thai bolted on. In the younger years, students learn simultaneously in Thai and English within the same classroom, taught side by side by native speaker teachers in each language. Moving into secondary school, subjects like maths, science, and history split into parallel Thai-language and English-language classes that are deliberately coordinated to reinforce one another, letting students work toward both Thai national exams and the IGCSE and A-Level track.\n\nThe school also brands itself around a Thinking School framework, developed in partnership with Exeter University, aimed at building critical and reflective thinking into everyday lessons rather than teaching purely to the test. That approach earned ANS Advanced Thinking School accreditation, membership in FOBISIA, and full CIS accreditation, making it the first bilingual school in Thailand to hold CIS status.\n\nThe central Bangkok campus, a short walk from Phaya Thai BTS station, has separate purpose built buildings for its Foundation, Primary, and Secondary phases, along with a 25 meter pool, a dedicated ballet studio, science labs, and a large football pitch at the heart of the site. Outside the regular timetable, the school runs one of the more extensive after school programs in the city, with more than 100 clubs spanning sports, robotics, performing arts, and language options including Mandarin and Japanese.\n\nEntry into the youngest year groups is largely first come, first served, while places from Year 1 onward are assessed through testing, an interview, and reports from the student\'s previous school. Given the school\'s reputation, popular year groups often carry a waiting list, founded in 1926, Amnuay Silpa counts six former Thai prime ministers among its alumni.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Thai", photo: "/images/schools/amnuay-silpa-school.jpg" },
  { name: "Invictus International Programme", slug: "invictus-international-programme", curricula: ["British"], budget: "over400k", website: "https://www.invictus.school", description: "Invictus is the Thailand branch of Invictus International School, a network founded in Singapore in 2015 that positions itself specifically as an affordable pathway into Cambridge-curriculum international education, spanning Years 1 through 13.\n\nThat explicit affordability positioning, combined with a genuine Cambridge curriculum framework, sets Invictus apart from schools that either charge premium fees for a similar curriculum or offer a lower-cost option without full Cambridge examination credentials.\n\nBeing part of a regional network originating in Singapore gives the Bangkok branch access to shared curriculum resources and institutional structure from the wider Invictus group, even as a relatively newer entrant into the Bangkok market compared to more established local schools.\n\nFamilies drawn to Invictus are typically specifically seeking that combination of genuine Cambridge curriculum credentials with a more accessible fee structure than many of Bangkok's other British curriculum options.", languageOfInstruction: "English" },
  { name: "RBIS International School", slug: "rbis-international-school", curricula: ["British"], budget: "over400k", website: "https://rbis.ac.th", description: "RBIS offers the English National Curriculum from Early Years through IGCSE, with post-16 pathways including A-Levels or BTEC, giving older students a choice between the traditional academic exam route and a more vocationally structured qualification.\n\nThe school keeps class sizes small, with Nursery capped at 12 students, and runs a dedicated English as an Additional Language program, which is a specific structural commitment to supporting non-native English speakers rather than treating language support as an informal add-on.\n\nThat combination of small capped class sizes and a formal EAL program makes RBIS a particular fit for families whose children are still building English fluency and want dedicated support built into the school's structure from the start.\n\nFamilies choosing RBIS are typically prioritizing that small-class, EAL-supported environment, alongside the flexibility of an A-Levels or BTEC choice at the post-16 stage.", languageOfInstruction: "English" },
  { name: "Singapore International School of Bangkok", slug: "singapore-international-school-of-bangkok", curricula: ["British", "International Baccalaureate", "Singaporean"], budget: "over400k", website: "https://www.sisb.ac.th", founded: 2001, description: "SISB Pracha Uthit is the flagship campus of SISB, the only education group listed on the Stock Exchange of Thailand, which gives the network a level of public financial transparency and scale that most privately held international school groups in Bangkok do not have.\n\nFounded in 2001, this campus teaches a combined Singapore and UK curriculum trilingually in English, Chinese, and Thai, a genuinely three-language academic structure that goes beyond the bilingual or English-medium-with-language-classes approach most other Bangkok schools use.\n\nAs the flagship of a six-campus national network, Pracha Uthit benefits from shared curriculum resources and institutional scale across SISB's other Thai locations, while still operating with its own local admissions and campus culture.\n\nFamilies specifically interested in a genuinely trilingual Singapore-curriculum education, rather than a British or American framework, are the core audience for SISB, distinguishing it clearly from the broader Bangkok international school market.", ageRange: "Nursery to Year 13", languageOfInstruction: "English, Chinese, Thai" },
  { name: "Norwich International School", slug: "norwich-international-school", curricula: ["International Baccalaureate", "British"], budget: "over400k", website: "https://www.norwichschool.ac.th", founded: 2014, description: "Norwich, founded in 2014, sits in southwest Bangkok near Samut Sakhon, following the British National Curriculum from EYFS through IGCSE, with the IB Diploma Programme offered in the final two years, a structural choice it shares with Bangkok Patana and Regent's rather than continuing straight through to A-Levels.\n\nThe school introduces Mandarin from Nursery age, giving students an early start on a third language well before secondary school, which is a more front-loaded approach to language learning than many British curriculum schools that add Mandarin later.\n\nThe Samut Sakhon-adjacent location places Norwich outside the central Bangkok cluster of international schools, making it a practical option for families based in that southwestern part of the greater Bangkok area rather than a typical choice for families prioritizing proximity to downtown.\n\nFamilies drawn to Norwich are typically weighing that specific combination of British curriculum through IGCSE, an IB Diploma finish, and early Mandarin exposure, in a location that suits families outside the central Sukhumvit corridor.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Sequoia Nova International Primary School", slug: "sequoia-nova-international-primary-school", curricula: ["French"], budget: "under400k", website: "https://sequoia-nova.com", founded: 2025, description: "Sequoia Nova opened in September 2025 in Sathorn as a joint venture between Acacia Education Group and WeLearn Academy, making it one of the newest schools in Bangkok's international education market and serving a deliberately narrow age range of 6 to 11 years old only.\n\nThe school runs two distinct tracks: an English-medium section aligned with US Common Core standards, and a French Bilingual section following the French national curriculum, giving families a genuine choice of academic language and framework within the same institution rather than a single fixed curriculum.\n\nBeing a joint venture with WeLearn Academy, which is known for a project-based, entrepreneurial approach to education, Sequoia Nova likely carries some of that learner-driven philosophy into its more traditional Common Core and French curriculum tracks, though as a primary-only school families will need to plan for a secondary school transition afterward.\n\nGiven how recently Sequoia Nova opened, it does not yet have an established local track record, and families considering it are weighing the appeal of its dual-track language structure and newer facilities against the lack of a proven history.", ageRange: "Ages 6 to 11", languageOfInstruction: "English, French" },
  { name: "Rose Marie Academy", slug: "rose-marie-academy", curricula: ["American"], budget: "over400k", website: "https://rose-marie.ac.th", description: "Rose Marie Academy is a small American-curriculum school based in Nonthaburi, serving families outside central Bangkok with a lower public profile than the city's larger international schools.\n\nAs a smaller school outside the main Sukhumvit cluster, Rose Marie tends to serve families already based in Nonthaburi or the northern greater Bangkok area, rather than competing directly for families weighing schools in the central city.\n\nDetailed public information on Rose Marie Academy's specific programs and history is limited compared to Bangkok's larger, more established international schools, so families interested in this school should plan on contacting admissions directly for detailed curriculum and fee information.\n\nFamilies considering Rose Marie Academy are typically doing so based on its Nonthaburi location and American curriculum, and should expect a smaller, less internationally networked school experience than the city's larger American curriculum options like ISB or Berkeley.", languageOfInstruction: "English" },
  { name: "XCL American School of Bangkok", slug: "xcl-american-school-of-bangkok", curricula: ["American"], budget: "over400k", website: "https://www.asbsk.ac.th", founded: 1983, description: "This Sukhumvit campus was originally opened in 1983 as Didyasarin International Kindergarten and operated for decades as part of the American School of Bangkok before being acquired by XCL Education in 2022 and rebranded XCL American School of Bangkok, making it institutionally distinct from the separate ASB Green Valley campus despite the shared history.\n\nThe school teaches an AP-integrated American curriculum from its location near Thong Lo, one of Bangkok's more central and well-connected expat neighborhoods, giving it a genuinely convenient location for families based in that part of the city.\n\nBecause this campus only recently separated from ASB under new ownership, families researching it should be careful to distinguish it clearly from ASB Green Valley, since the two now operate as separate schools with different ownership despite originating from the same institution.\n\nFamilies choosing XCL American School of Bangkok are typically drawn to its central Thong Lo location and AP-integrated American curriculum, understanding that its recent change in ownership means a shorter track record under its current XCL branding specifically.", languageOfInstruction: "English" },
  { name: "Thai-Singapore International School", slug: "thai-singapore-international-school", curricula: ["British", "Singaporean"], budget: "unknown", description: "Thai-Singapore International School is a smaller Bangkok school combining British and Singaporean curriculum elements, part of the city's broader network of Singapore-style education providers alongside larger operators like SISB.\n\nAs a smaller, less internationally networked school than SISB's multi-campus operation, Thai-Singapore International School likely offers a more locally focused version of the Singapore curriculum approach, blended with British curriculum elements rather than a purely Singapore-standard program.\n\nDetailed public information on this school's specific facilities, fees, and track record is limited compared to Bangkok's larger international schools, so families interested should plan on contacting the school directly for current details.\n\nFamilies specifically interested in a British-Singaporean curriculum blend, but who want a smaller school than the larger SISB network, are the natural audience for Thai-Singapore International School.", languageOfInstruction: "English" },
  { name: "Bangkok Adventist International School", slug: "bangkok-adventist-international-school", curricula: ["American", "Adventist"], budget: "unknown", website: "https://bais.ac.th", description: "Bangkok Adventist International School is a Seventh-day Adventist school offering an American curriculum, part of the same Adventist education network that also operates Ekamai International School in Bangkok, giving the two schools a shared denominational and institutional background despite operating as separate campuses.\n\nAs a Seventh-day Adventist institution, the school carries a specific religious identity distinct from the Catholic, generically Christian, or Korean missionary-founded schools elsewhere in Bangkok's faith-based school landscape.\n\nBeing part of the same broader Adventist network as Ekamai gives Bangkok Adventist International School some shared institutional resources and denominational consistency, even though each campus operates with its own local admissions, campus, and community.\n\nFamilies specifically seeking a Seventh-day Adventist, American curriculum education have both this school and Ekamai as options within the same denominational network in Bangkok.", languageOfInstruction: "English" },
  { name: "Rising Oaks International School Bangkok", slug: "rising-oaks-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://roisb.ac.th", founded: 2006, description: "Rising Oaks, established in 2006, follows the National British Curriculum from Nursery through Year 11, with average class sizes of 20 to 25 students, giving it a mid-range class size compared to the smaller capped classes at schools like RBIS or the larger classes at bigger institutions.\n\nThe school maintains a full calendar of school events including Songkran and other international celebrations, reflecting a deliberate effort to blend Thai cultural events into the regular school calendar alongside its British curriculum academics.\n\nCurrently extending through Year 11 rather than a full A-Level or IB sixth form, Rising Oaks families need to plan for a transition to a different school for the final two years of secondary education, similar to the situation at several of Bangkok's other Year 11-capped schools.\n\nFamilies drawn to Rising Oaks are typically prioritizing its established British curriculum through Year 11, mid-sized classes, and culturally blended school calendar, while planning ahead for the eventual sixth form transition.", ageRange: "Nursery to Year 11", languageOfInstruction: "English" },
  { name: "Astra Academy International School", slug: "astra-academy-international-school", curricula: ["British"], budget: "over400k", website: "https://www.astra.ac.th", description: "Astra Academy is a UK-curriculum school in Bangkok's Ekkamai neighborhood, built around what the school describes as a future-focused, student-centered approach rather than a traditional exam-first academic model.\n\nFacilities include an eco garden, a dedicated cooking classroom, and a swimming pool, reflecting an emphasis on hands-on, practical learning experiences alongside the standard academic curriculum, similar in spirit to some of the more experiential approaches at schools like Roong Aroon, though built around a British rather than IB framework.\n\nThe central Ekkamai location makes Astra Academy convenient for families already living in that popular expat neighborhood, without needing to travel to a more suburban or outlying campus.\n\nFamilies drawn to Astra Academy are typically interested in that specific combination of a British curriculum foundation with a more experiential, hands-on approach to daily learning, in a central and convenient Ekkamai location.", languageOfInstruction: "English" },
  { name: "WeLearn Academy", slug: "welearn-academy", curricula: ["American", "British", "Thai"], budget: "under400k", website: "https://welearnthailand.com", description: "WeLearn Academy was founded by educator David Doran as a project-based alternative to traditional schooling, focused on entrepreneurship, real-world skills, and learner-driven education rather than a conventional curriculum structure built around fixed subjects and grade levels.\n\nThat project-based, entrepreneurial philosophy is a genuinely different approach from nearly every other school in Bangkok, most of which follow a recognized national curriculum like British, American, or IB with standard examination pathways.\n\nWeLearn is also the co-founder behind the newer Sequoia Nova International Primary School, which opened in 2025, extending its learner-driven philosophy into a more structured Common Core and French bilingual primary framework through that joint venture.\n\nFamilies drawn to WeLearn Academy are typically specifically seeking that alternative, project-based educational philosophy, rather than comparing it directly against Bangkok's mainstream curriculum-based international schools.", languageOfInstruction: "English, Thai" },
  { name: "St. Mark's International School", slug: "st-marks-international-school", curricula: ["Australian", "Singaporean"], budget: "unknown", website: "https://stmarks.ac.th", founded: 1999, description: "St. Mark's, founded in 1999, holds the distinction of being the first Australian international school established in Thailand, and is a Christian school in the Suan Luang district teaching an Australian and Singapore curriculum at primary level before moving to IGCSE and A-Levels in secondary.\n\nThat combination of Australian and Singapore curriculum influence at the primary stage, transitioning to a more standard British exam pathway later, is a distinctive structural choice that sets St. Mark's apart from most other Bangkok schools, which typically stick with a single curriculum framework throughout.\n\nAs an explicitly Christian school, St. Mark's shares some mission similarities with ICS, Bangkok Christian International, and Ekamai, though each carries its own specific denominational background and, in St. Mark's case, a distinctly Australian rather than American curriculum foundation.\n\nFamilies drawn to St. Mark's are typically interested in that specific Australian-Singapore primary curriculum combined with a Christian mission and an eventual British exam pathway in the later years.", languageOfInstruction: "English" },
  { name: "Australian International School Bangkok", slug: "australian-international-school-bangkok", curricula: ["British", "Australian"], budget: "over400k", website: "https://www.australianisb.ac.th", founded: 2002, description: "AISB was founded in 2002, originally registered under the name Aucksara International School before adopting its current Australian-branded identity. It sits in the Sukhumvit area and serves a genuinely broad international community, with students representing more than 40 nationalities.\n\nThe school follows an Australian and British-influenced curriculum blend rather than a single national curriculum framework, which is a somewhat distinctive academic positioning compared to the more standard British or American curriculum choices most other Bangkok international schools offer.\n\nAs a mid-sized school in a well-connected Sukhumvit location, AISB tends to appeal to families who want an established international curriculum without the scale of the city's largest schools, and who are specifically interested in an Australian-influenced educational approach.\n\nWith over two decades of operating history now, AISB has moved well past its early years as Aucksara International School and built its own identity and reputation under the Australian International School branding it has carried for most of its history.", languageOfInstruction: "English" },
  { name: "International Christian School Nonthaburi", slug: "international-christian-school-nonthaburi", curricula: ["American", "Christian"], budget: "over400k", website: "https://icsn.ac.th", description: "International Christian School Nonthaburi, often abbreviated ICSN, began in 1983 as Panda Kindergarten before expanding in 1997 and adopting the name Global English School, then transitioning to its current identity as ICSN in March 2022, reflecting a gradual institutional evolution over four decades.\n\nThat naming history is worth knowing for families researching Bangkok schools, since ICSN shares direct institutional roots with what is separately listed elsewhere as Global English School, and families may encounter references to either name depending on the source.\n\nAs a Christian school in Nonthaburi, ICSN serves families in that northern greater Bangkok area specifically, joining a smaller cluster of international schools based outside the central city.\n\nFamilies researching ICSN should confirm its current curriculum structure and note its shared history with the Global English School name when comparing information from different sources.", languageOfInstruction: "English" },
  { name: "Beaconhouse Yamsaard International School", slug: "beaconhouse-yamsaard-international-school", curricula: ["British"], budget: "under400k", website: "https://bys.ac.th", description: "Beaconhouse Yamsaard is part of the Beaconhouse School System, a global network with over 1,000 schools that originated in Pakistan, making it one of the larger international education groups with a presence in Bangkok, alongside networks like Nord Anglia and Cognita.\n\nThe school operates multiple campuses across Thailand, including Ladprao, Rangsit, Hua Hin, and Pattanakarn, serving more than 3,800 students in total across all locations, a genuinely large combined enrollment compared to most single-campus Bangkok international schools.\n\nBeing part of such a large global network gives Beaconhouse Yamsaard access to shared curriculum resources and institutional scale, though families should confirm which specific Thai campus they are researching, since facilities and programs can vary meaningfully between the Ladprao, Rangsit, Hua Hin, and Pattanakarn sites.\n\nFamilies drawn to Beaconhouse Yamsaard are typically interested in that global network backing and the choice of multiple campus locations across greater Bangkok and beyond.", languageOfInstruction: "English, Thai" },
  { name: "BSB British International Primary School", slug: "bsb-british-international-primary-school", curricula: ["British"], budget: "over400k", website: "https://bsbangkok.ac", founded: 1992, description: "BSB, founded in March 1992 on Sukhumvit Soi 4, is a primary-only school covering EYFS through Year 6, with a deliberately close-knit community of around 180 students from over 40 nationalities, a notably small scale for a school in such a central Sukhumvit location.\n\nThe school maintains a notably low teacher-to-student ratio in Nursery specifically, reflecting a deliberate choice to prioritize individual attention for its youngest students over class size efficiency.\n\nAs a primary-only school, families using BSB need to plan for a transition to a separate secondary school once children complete Year 6, similar to the situation at the Cognita St Andrews Sathorn and Dusit campuses, though BSB operates independently of that network.\n\nFamilies drawn to BSB are typically prioritizing that combination of a small, genuinely international primary community and central Sukhumvit location, accepting the need to plan a secondary school transition in advance.", ageRange: "Ages 2 to 11", languageOfInstruction: "English" },
  { name: "Crescent International School", slug: "crescent-international-school", curricula: ["British"], budget: "unknown", website: "https://cis.ac.th", founded: 2008, description: "Crescent, established in 2008 in the heart of Sathorn, is one of the only schools in Thailand offering Arabic, Thai, and Islamic Studies up to IGCSE level alongside a strong maths and science focus, following the National Curriculum for England as its core academic framework.\n\nThat specific combination of British curriculum academics with dedicated Arabic and Islamic Studies instruction makes Crescent a genuine niche option, serving Bangkok's Muslim community and any family specifically interested in that religious and language education alongside a standard British exam pathway.\n\nThe central Sathorn location places Crescent within easy reach of families already living in that part of Bangkok, without requiring a longer commute to a more suburban campus.\n\nFamilies specifically seeking Arabic language instruction and Islamic Studies within a genuine British IGCSE curriculum framework have Crescent as one of the few, if not the only, options offering that particular combination in Bangkok.", languageOfInstruction: "English" },
  { name: "Royce Royal International School", slug: "royce-royal-international-school", curricula: ["British"], budget: "under400k", website: "https://www.royceroyal.ac.th", description: "Royce Royal International School is a British-curriculum school serving Bangkok families, part of the city's broader range of mid-sized international school options operating outside the larger UK-affiliated networks like Nord Anglia or Cognita.\n\nAs an independently branded school rather than part of a larger international group, Royce Royal likely has more flexibility in shaping its own specific culture and program details, though this also means less access to the shared institutional resources that networked schools benefit from.\n\nDetailed public information on Royce Royal's specific facilities, fees, and track record is more limited than for Bangkok's larger, more established international schools, so families interested should plan on contacting the school directly for current details.\n\nFamilies considering Royce Royal are typically weighing it against Bangkok's other independently run, mid-sized British curriculum schools on the basis of location and specific program fit.", languageOfInstruction: "English" },
  { name: "Dulwich College International School Bangkok", slug: "dulwich-college-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://bangkok.dulwich.org", founded: 2026, description: "Dulwich College International School Bangkok is the newest addition to Bangkok's international school market, opening in August 2026 in the Bang Na district as the first Dulwich College International campus in Thailand. The physical campus was designed around a traditional Thai village-style layout rather than a standard international school building template.\n\nAcademically, it follows the English National Curriculum through IGCSE, then gives students a choice between the IB Diploma Programme and A-Levels in the final two years, a structural flexibility that puts it in a similar category to Regent's and Bangkok Patana in offering an IB option alongside a British foundation.\n\nThe school is part of the global Dulwich College International network, which itself traces its roots to Dulwich College London, founded in 1619, giving the Bangkok campus access to a long institutional lineage and a network of sister campuses across Asia even though the Bangkok site itself just opened.\n\nGiven how recently Dulwich Bangkok opened, it does not yet have local exam results or an established reputation the way Bangkok's longer running schools do. Families considering it are weighing the appeal of a well-resourced new campus and strong global network against the lack of a proven local track record.", ageRange: "Ages 3 to 18 (opening with Nursery to Year 6, expanding through 2029)", languageOfInstruction: "English" },
  { name: "Thai-Chinese International School", slug: "thai-chinese-international-school", curricula: ["American"], budget: "over400k", website: "https://www.tcis.ac.th", description: "Thai-Chinese International School (TCIS) is a member of the Bangkok International Schools Athletic Conference, fielding teams across football, basketball, volleyball, golf, swimming, and other sports as part of its American curriculum program, giving it a genuinely competitive interscholastic sports presence.\n\nThat BISAC membership places TCIS within the same competitive sporting circuit as several of Bangkok's larger international schools, meaning students have access to a fairly serious level of interscholastic athletics alongside their regular academic program.\n\nAs a school with both Thai and Chinese cultural elements built into its name and likely its community, TCIS may appeal specifically to families with connections to either the Thai or Chinese communities in Bangkok, alongside its standard American curriculum framework.\n\nFamilies drawn to TCIS are typically interested in that combination of a genuine American curriculum with active BISAC sports participation, within a school community reflecting both Thai and Chinese cultural ties.", languageOfInstruction: "English, Chinese" },
  { name: "Kids Academy International School", slug: "kids-academy-international-school", curricula: ["British", "Chinese", "Japanese"], budget: "unknown", website: "https://www.kidsacademy.ac.th", description: "Kids Academy is a smaller international pre-school in Bangkok offering British curriculum foundations alongside Chinese and Japanese language exposure, giving young children an early introduction to multiple languages beyond the standard English-medium instruction.\n\nThat specific combination of British early years curriculum with both Chinese and Japanese language elements is a distinctive positioning among Bangkok's early years providers, most of which focus on English instruction with at most one additional language.\n\nAs a preschool specifically, Kids Academy functions as an early years starting point rather than a full K-12 school, meaning families will need to plan for a transition to a primary school once children age out, similar to Tiny Tots, KiddyKare, or IPC.\n\nFamilies drawn to Kids Academy are typically interested in that early multilingual exposure to Chinese and Japanese specifically, alongside a standard British early years curriculum foundation.", languageOfInstruction: "English" },
  { name: "Ramkhamhaeng Advent International School", slug: "ramkhamhaeng-advent-international-school", curricula: ["Adventist", "American"], budget: "under400k", website: "https://www.rais.ac.th", founded: 1999, description: "RAIS, founded in 1999 by Mr. Udom Srikureja, is a Seventh-day Adventist school in Bang Kapi following a structured American curriculum, serving around 700 students with active sports programs including basketball, swimming, and badminton.\n\nAs a Seventh-day Adventist institution, RAIS shares denominational roots with Ekamai and Bangkok Adventist International School, giving Bangkok families three Adventist-affiliated school options across different parts of the city, each operating as its own separate campus and community.\n\nWith around 700 students, RAIS is a mid-sized school by Bangkok international school standards, larger than many of the city's smaller independent schools but well below the scale of ISB, Patana, or NIST.\n\nFamilies specifically seeking a Seventh-day Adventist, American curriculum school in the Bang Kapi area have RAIS as a genuine local option, alongside the denominationally related but differently located Ekamai and Bangkok Adventist campuses.", languageOfInstruction: "English" },
  { name: "Pan-Asia International School", slug: "pan-asia-international-school", curricula: ["International Baccalaureate", "American"], budget: "unknown", website: "http://www.pais.ac.th", founded: 2004, description: "PAIS was founded in 2004 in the Prawet district, roughly 10 kilometers from Suvarnabhumi Airport, and follows American academic standards with a deliberate emphasis on Eastern culture woven into the curriculum rather than treated as a separate cultural program.\n\nThe school serves students from more than 40 nations, a genuinely broad international mix for a school of its size, and its airport-adjacent location makes it a practical option for families who travel frequently or work in aviation-related industries based near Suvarnabhumi.\n\nThat explicit blending of American academic standards with Eastern cultural emphasis is a specific point of difference from Bangkok's other American curriculum schools, most of which follow a more standard US-style program without that particular cultural framing.\n\nFamilies choosing PAIS are often specifically drawn to that combination of American academics with Eastern cultural grounding, alongside the practical convenience of its location near Suvarnabhumi Airport.", languageOfInstruction: "English" },
  { name: "NIVA American International School", slug: "niva-american-international-school", curricula: ["American", "Christian"], budget: "over400k", website: "https://www.niva.ac.th", founded: 1991, description: "NIVA was founded in 1991 in the Bang Kapi area, and the school's name comes directly from the founders' own children, Nicholas and Vanisara, giving it a genuinely family-founded origin story similar to Charter International School. It follows a North American curriculum with AP course offerings available in high school.\n\nThe school marked its 30th anniversary in 2021, giving it more than three decades of local operating history, a meaningful track record for a family-founded American curriculum school of its size.\n\nAs a family-founded rather than corporately owned or internationally networked school, NIVA has more independence in shaping its specific culture and priorities, similar in structure to Charter or KPIS, though with a North American rather than British curriculum focus.\n\nFamilies choosing NIVA over Bangkok's larger American schools like ISB or Berkeley are typically looking for a smaller, more established family-run alternative with a genuine multi-decade history in the same Bang Kapi location.", ageRange: "Ages 3 to 18", languageOfInstruction: "English" },
  { name: "John Wyatt Montessori Bangkok", slug: "john-wyatt-montessori-bangkok", curricula: ["American", "Montessori"], budget: "unknown", website: "https://www.jwmontessori.com", description: "John Wyatt Montessori Bangkok is an American-curriculum school built around Montessori teaching principles, offering child-led early learning, joining Montessori Academy Bangkok and International Montessori Center among the city's Montessori-method providers.\n\nThe Montessori approach specifically emphasizes self-directed activity, hands-on learning materials, and mixed-age classrooms, a distinctly different pedagogical philosophy from the more conventional instruction most Bangkok international schools follow.\n\nFamilies specifically seeking Montessori methodology within an American curriculum framework would compare John Wyatt Montessori against Montessori Academy Bangkok, both of which share that same general approach and curriculum base.\n\nFamilies interested should confirm current age ranges served and how far through a child's education the school carries its Montessori approach, since programs of this type vary in scope.", languageOfInstruction: "English" },
  { name: "SPGS International School Bangkok", slug: "spgs-international-school-bangkok", curricula: ["British"], budget: "over400k", founded: 2026, description: "SPGS is a newer addition to Bangkok's British-curriculum school options, opening in 2026, which means it enters the market without an established local track record but with the opportunity to build purpose-designed facilities and systems from scratch rather than expanding an older site.\n\nAs with other very recently opened schools like Wycombe Abbey, Dulwich College Bangkok, and Sequoia Nova, families considering SPGS should factor in that lack of proven local history against the appeal of joining a brand new school during its founding years.\n\nDetailed information on SPGS's specific curriculum structure, facilities, and fees will become clearer as the school establishes itself locally, so families interested in this option should plan on contacting the school directly for the most current details.\n\nFamilies drawn to newly opened schools like SPGS are typically weighing the appeal of new facilities and a fresh institutional start against the track record and proven results that Bangkok's more established schools can offer.", languageOfInstruction: "English" },
  { name: "New Day Learning", slug: "new-day-learning", curricula: ["Special Educational Needs"], budget: "unknown", website: "https://newdaylearningco.com", description: "New Day Learning is a Bangkok school specializing in education for students with special educational needs, distinct from the city's mainstream international school options that serve the general student population.\n\nSchools focused specifically on special educational needs, like New Day Learning and The Village International Education Centre (VIE) elsewhere in Bangkok, fill a genuinely different role from mainstream international schools, often incorporating therapists and individualized education plans as a core part of daily operations rather than an add-on support service.\n\nFamilies seeking a dedicated special needs education environment, rather than a mainstream school with some learning support services layered on, would specifically research schools like New Day Learning as a primary option rather than a backup choice.\n\nFamilies interested in New Day Learning should contact the school directly to understand its specific specializations, therapeutic staff, and admissions process, since this kind of specialized school typically requires more individualized conversations than a standard mainstream school inquiry.", languageOfInstruction: "English" },
  { name: "British Mandarin International School", slug: "british-mandarin-international-school", curricula: ["British", "Chinese"], budget: "over400k", website: "https://bmis.ac.th", description: "British Mandarin International School is a British-curriculum school in Bangkok with a dedicated Mandarin Chinese language program woven into daily instruction, aimed at families wanting a bilingual British-style education rather than English-only instruction with Mandarin as a minor add-on subject.\n\nThat deep integration of Mandarin into the regular curriculum, rather than treating it as a single additional class period, is a meaningful commitment that distinguishes this school from British curriculum providers that offer only occasional Mandarin lessons.\n\nFamilies specifically seeking genuine bilingual English-Mandarin instruction within a British curriculum framework, rather than a British school with token Chinese language classes, are the natural audience for this school.\n\nFamilies interested should confirm the specific level of Mandarin integration and instructional hours directly with the school, since bilingual programs can vary considerably in intensity.", languageOfInstruction: "English, Chinese" },
  { name: "Lertlah School", slug: "lertlah-school", curricula: ["Canadian"], budget: "unknown", website: "https://lertlah.com", description: "Lertlah School follows the Canadian curriculum, offering Bangkok families an alternative to the more common British and American curriculum options that dominate the city's international school market.\n\nAs one of only a small number of Canadian curriculum providers in Bangkok, alongside British Columbia International School and Canadian International School of Thailand, Lertlah gives families genuine choice among Canadian provincial curriculum frameworks, though each of these schools follows a different specific Canadian system.\n\nFamilies specifically seeking a Canadian curriculum, particularly those with prior experience in the Canadian school system or planning an eventual return to Canada for university, form the core audience for Lertlah rather than families simply comparing generic international school options.\n\nDetailed information on Lertlah's specific facilities and fees is best confirmed directly with the school, as public documentation is more limited than for Bangkok's larger, more established international school groups.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Sathorn", slug: "st-andrews-international-school-sathorn", curricula: ["British"], budget: "over400k", website: "https://www.standrewssathorn.com", founded: 2003, description: "St Andrews Sathorn opened in January 2003 in a renovated former hospital building near Silom, one of three Bangkok campuses run by the Cognita group under the St Andrews name, entirely separate from the unrelated Nord Anglia-owned St Andrews International School Bangkok elsewhere in the city.\n\nThe Sathorn campus is primary-only, covering Nursery through Year 6, with students typically continuing to the Sukhumvit 107 campus for secondary school within the same Cognita network, creating a structured two-campus pathway for families who start at Sathorn.\n\nThe central Sathorn and Silom location makes this campus convenient for families based in that part of the city, though the eventual need to transition to Sukhumvit 107 for secondary school is worth factoring into location planning from the start.\n\nFamilies should take care not to confuse this Cognita-owned campus with the separate, unrelated Nord Anglia St Andrews International School Bangkok, despite the identical branding.", ageRange: "Ages 2 to 11 (Nursery to Year 6)", languageOfInstruction: "English" },
  { name: "Westminster College Bangkok", slug: "westminster-college-bangkok", curricula: ["American", "British"], budget: "unknown", website: "https://westminster.ac.th", description: "Westminster College Bangkok blends American and British curriculum elements, part of the city's wider mix of combined-curriculum international schools that do not commit to a single national framework.\n\nThat blended approach can appeal to families who want elements of both systems, such as US-style continuous assessment alongside British-style examinations, though it also means Westminster's specific academic structure is worth confirming directly rather than assuming it matches either a pure American or pure British program.\n\nAs an independently branded school rather than part of a larger UK or American institutional network, Westminster College has more flexibility in shaping its own specific blended curriculum approach and school culture.\n\nFamilies drawn to Westminster College are typically interested in that specific American-British blend, and should confirm current curriculum details and exam pathways directly with the school given the hybrid structure.", languageOfInstruction: "English" },
  { name: "Modern International School Bangkok", slug: "modern-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://www.misb.ac.th", founded: 1997, description: "MISB was established in 1997 on Sukhumvit Soi 39, and follows the National British Curriculum from Nursery through Year 13, offering IGCSE and A-Level examinations as an accredited Cambridge International Examinations center, meaning exams are administered on-site rather than requiring travel to a separate testing location.\n\nBeing an accredited Cambridge exam center specifically is a practical detail that matters for families and students, since it means the full examination process, not just the teaching, happens within the school's own infrastructure.\n\nWith nearly three decades of history on the same Sukhumvit Soi 39 site, MISB has a longer established local track record than many of Bangkok's more recently opened British curriculum schools, without the UK institutional affiliation that Harrow, Shrewsbury, or Wellington carry.\n\nFamilies choosing MISB are typically looking for a straightforward, independently run British curriculum school with a solid local history and direct Cambridge exam center status, in a well-connected Sukhumvit location.", ageRange: "Nursery to Year 13", languageOfInstruction: "English" },
  { name: "Thai International School", slug: "thai-international-school", curricula: ["American"], budget: "over400k", website: "https://thaiinternationalschool.ac.th", description: "Thai International School is a WASC-accredited American curriculum school on a 30-rai riverside campus in Pathum Thani, currently serving Nursery through Grade 6, making it a primary-focused school rather than a full K-12 institution at this stage.\n\nThe school places a specific emphasis on preserving Thai manners and customs alongside its American academic framework, a deliberate cultural grounding that distinguishes it from American schools that operate with a more purely US-style approach and less explicit local cultural integration.\n\nBeing currently limited to Nursery through Grade 6 means families using Thai International School will need to plan for a transition to a different secondary school once their children progress beyond primary level, similar to the situation at Centurion or Tiny Tots at earlier stages.\n\nFamilies drawn to Thai International School are typically interested in that specific combination of WASC-accredited American academics with explicit Thai cultural grounding, on a spacious Pathum Thani riverside campus.", ageRange: "Nursery to Grade 6", languageOfInstruction: "English" },
  { name: "Satit Pattana Secondary School", slug: "satit-pattana-secondary-school", curricula: ["British"], budget: "unknown", website: "https://www.satitpattana.ac.th", description: "Satit Pattana is a British-curriculum secondary school in Bangkok, part of the city's Satit, or demonstration school, network affiliated with Thai universities, a structure common in Thai education where universities operate attached schools for practical teacher training and educational research purposes.\n\nThat university affiliation distinguishes Satit Pattana from most other British curriculum schools in Bangkok, which typically operate as independent institutions or as part of international school groups rather than being tied to a Thai university's education faculty.\n\nAs a secondary-focused school specifically, Satit Pattana serves the later years of a student's education, meaning families typically need a separate primary school for the earlier years before transitioning to Satit Pattana for secondary study.\n\nFamilies interested in Satit Pattana's specific university affiliation and British secondary curriculum should confirm current admissions requirements and any prerequisites tied to its demonstration school structure.", languageOfInstruction: "English" },
  { name: "Kincaid International School of Bangkok", slug: "kincaid-international-school-of-bangkok", curricula: ["International Baccalaureate"], budget: "under400k", website: "https://www.kincaidbangkok.com", description: "Kincaid is an IB-curriculum school in Bangkok offering the International Baccalaureate framework as its core academic program, joining a smaller group of Bangkok schools built specifically around IB rather than adding it as an option alongside a British or American base.\n\nAs an IB-focused school, Kincaid sits alongside NIST, KIS, Ascot, and Roong Aroon among Bangkok's providers of the full or partial IB continuum, though each of these schools differs in scale, campus location, and which specific parts of the IB continuum they are authorized to teach.\n\nFamilies specifically prioritizing IB-style inquiry-based learning from an early age, rather than a British or American curriculum with an IB Diploma added only in the final years, would compare Kincaid against Bangkok's other genuinely IB-first schools.\n\nFamilies interested in Kincaid should confirm the specific IB programmes the school is currently authorized to teach, since IB authorization can vary by programme level and may change as the school develops.", languageOfInstruction: "English" },
  { name: "Siam International School", slug: "siam-international-school", curricula: ["British"], budget: "over400k", website: "https://www.siamis.ac.th", description: "Siam International School sits on a 40-rai campus in Thanyaburi, Pathum Thani, authorized by Thailand's Ministry of Education from kindergarten through Grade 6, with a curriculum emphasis specifically on self-development alongside standard academics.\n\nThat self-development curriculum emphasis is a distinctive framing compared to most Bangkok international schools, which typically lead with their national curriculum and examination board rather than a specific pedagogical philosophy as the primary description.\n\nThe large 40-rai campus in Pathum Thani gives Siam International School considerably more physical space than most central Bangkok schools, though the location places it well outside the city center for families not already based in that northern greater Bangkok area.\n\nAs a school currently serving kindergarten through Grade 6 only, families will need to plan for a secondary school transition once children progress beyond primary level, similar to several other primary-focused schools in Bangkok's wider international school landscape.", ageRange: "Kindergarten to Grade 6", languageOfInstruction: "English" },
  { name: "Wycombe Abbey International School Bangkok", slug: "wycombe-abbey-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://wycombeabbey.ac.th", founded: 2026, description: "Wycombe Abbey International School Bangkok opened in August 2026 on the former VERSO International School campus near Suvarnabhumi Airport, making it one of the newest entrants into Bangkok's British school market. It is affiliated with Wycombe Abbey in the UK, a school with roots going back to 1896, giving the Bangkok campus a genuine historical lineage despite being brand new locally.\n\nThe school follows a British curriculum through IGCSE and A-Levels, and notably offers a full boarding program alongside day places, which is relatively unusual among Bangkok's international schools and puts it in the same small group as Harrow in offering that option.\n\nBecause the campus is inherited from VERSO rather than purpose built from scratch, families researching Wycombe Abbey Bangkok should expect a transition period as the new operator establishes its own systems, culture, and track record on a site with an existing physical footprint but a completely new institutional identity.\n\nGiven how recently it opened, Wycombe Abbey does not yet have a local exam results history or established reputation the way Bangkok's longer running UK-affiliated schools do, which is worth factoring in for families prioritizing a proven track record over the appeal of joining at the ground floor of a new school.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Dusit", slug: "st-andrews-international-school-dusit", curricula: ["British"], budget: "over400k", website: "https://www.standrewsdusit.com", description: "St Andrews Dusit is a primary-only campus in the Dusit area, one of three Bangkok campuses run by the Cognita group under the St Andrews name, offering the English National Curriculum to children aged 2 through 11 before they typically move on to secondary school at the Cognita network's Sukhumvit 107 campus.\n\nThe Dusit location places this campus in a different part of the city from Sathorn or Sukhumvit 107, giving Cognita's St Andrews network reasonable geographic coverage across Bangkok for families seeking a primary-level entry point close to home before the secondary transition.\n\nAs a primary-only site, families using St Andrews Dusit need to plan for the eventual move to Sukhumvit 107, or another secondary school entirely, once their child completes Year 6, similar to the structure at the Sathorn campus.\n\nFamilies should take care not to confuse this Cognita-owned campus with the separate, unrelated Nord Anglia St Andrews International School Bangkok, despite the identical branding across both networks.", ageRange: "Ages 2 to 11 (Nursery to Year 6)", languageOfInstruction: "English" },
  { name: "Siam Singapore International School", slug: "siam-singapore-international-school", curricula: ["British", "Singaporean"], budget: "unknown", description: "Siam Singapore International School is a Bangkok school combining British and Singaporean curriculum elements, part of the city's network of Singapore-style education providers alongside Glory Singapore and the larger SISB network.\n\nAs a smaller, less internationally networked school than SISB's multi-campus operation, Siam Singapore likely offers a more intimate, locally focused version of that Singapore-influenced curriculum blended with British elements.\n\nFamilies specifically interested in a British-Singaporean curriculum blend, but who want a smaller school than SISB, would compare Siam Singapore against Glory Singapore and Thai-Singapore International School as similarly positioned options.\n\nFamilies researching Siam Singapore should confirm current curriculum structure, fees, and facilities directly with the school for the most up to date details.", languageOfInstruction: "English" },
  { name: "Aster International School Bangkok", slug: "aster-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://aster.ac.th", description: "A newer addition to Bangkok's school scene, built on a purpose-built campus in the city center. Aster combines an enhanced British international curriculum with project and theme-based learning, giving younger students an open-ended, learning-without-limits approach before moving into a more structured primary program.\n\nThat progression from open-ended, project-based early learning toward more structured primary instruction is a deliberate pedagogical design choice, aiming to build foundational curiosity and engagement before shifting toward more conventional academic structure as students get older.\n\nBeing purpose-built rather than adapted from an older site, Aster's central campus reflects modern school design from the outset, similar to how several of Bangkok's other recently opened schools like Dulwich College Bangkok or King's College have approached their facilities.\n\nFamilies drawn to Aster are typically interested in that specific blend of enhanced British curriculum with project and theme-based early learning, in a central, purpose-built city campus.", languageOfInstruction: "English" },
  { name: "RIS Swiss Section Deutschsprachige Schule Bangkok", slug: "ris-swiss-section-deutschsprachige-schule-bangkok", curricula: ["Swiss", "International", "German"], budget: "over400k", website: "https://ris-swiss-section.org", description: "The RIS Swiss Section is a German-language section operating within the Ruamrudee International School system, offering a Swiss-German curriculum pathway specifically for German-speaking families in Bangkok, an unusual arrangement that reflects how large and diverse RIS's overall student population has become.\n\nBeing embedded within the larger RIS campus means Swiss Section students have access to RIS's broader facilities and community, even while following a distinct German-language curriculum track separate from the main American and IB pathways RIS otherwise offers.\n\nThis arrangement is genuinely unusual in Bangkok, where most schools offering a specific national curriculum, whether French, Canadian, or German, operate as fully standalone institutions rather than as a section within a larger, differently curriculumed school.\n\nFamilies specifically seeking German-language, Swiss-curriculum education in Bangkok have the RIS Swiss Section as a genuinely distinctive option, combining that specific curriculum with the resources of one of Bangkok's largest international school campuses.", languageOfInstruction: "German, English" },
  { name: "Lycée Français International de Bangkok", slug: "lycee-francais-international-de-bangkok", curricula: ["French"], budget: "over400k", website: "http://www.lfib.ac.th", description: "Lycée Français International de Bangkok is a French curriculum school in the Wang Thonglang district teaching elementary through high school levels, following the French national education system rather than a British, American, or IB framework, making it Bangkok's primary option for families wanting a genuinely French academic pathway.\n\nEnglish and Thai are also taught as part of the program alongside French, giving students a trilingual foundation even though French remains the core language of instruction and curriculum structure throughout.\n\nAs the main French curriculum option in the city, LFIB serves French expatriate families specifically, as well as other international families interested in a French-medium education and eventual pathway toward French universities or the broader francophone education system.\n\nFamilies choosing LFIB are typically doing so for specific curriculum and language reasons tied to French educational continuity, rather than comparing it directly against Bangkok's British, American, or IB mainstream options.", languageOfInstruction: "French, English, Thai" },
  { name: "TSI International School", slug: "tsi-international-school", curricula: ["British"], budget: "under400k", website: "https://tsi.ac.th", founded: 1985, description: "TSI, formerly known as Thai Sikh International School, has operated since 1985 and now runs two campuses, including its main Bearing site near Bearing BTS station in Samut Prakan, serving students from Pre-Nursery through Year 13 across its full continuum.\n\nThe school's original name and founding reflect roots in Bangkok's Sikh community, though it has broadened its identity and enrollment considerably since 1985 under its current TSI branding, similar to how several other Bangkok schools have evolved their public identity over time while retaining their founding institutional base.\n\nWith four decades of operating history and a full Pre-Nursery through Year 13 continuum across two campuses, TSI offers families a genuinely long-established, single-network option without needing to transition between separate primary and secondary schools.\n\nFamilies researching TSI should confirm which of the two campuses they are considering, since facilities and exact program details can differ between the main Bearing site and the school's second location.", languageOfInstruction: "English" },
  { name: "Future Steps International School Bangkok", slug: "future-steps-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://thefirststeps.ac.th", description: "Future Steps International School Bangkok is a British-curriculum school, part of the city's broad range of mid-sized international education options operating independently of the larger UK-affiliated networks.\n\nAs an independently run school, Future Steps has flexibility in shaping its own specific program and culture, similar to Bangkok's other independently branded British curriculum schools like RC International or Pensmith.\n\nFamilies researching Future Steps should confirm current curriculum structure, examination pathway, and fees directly with the school, since detailed public information is more limited than for Bangkok's larger, more established international schools.\n\nFamilies comparing Future Steps against Bangkok's other independently run, mid-sized British curriculum schools are typically weighing location and specific program fit.", languageOfInstruction: "English" },
  { name: "King Mongkut's International Demonstration School", slug: "king-mongkuts-international-demonstration-school", curricula: ["American"], budget: "over400k", website: "https://www.kmids.ac.th", description: "KMIDS was developed under King Mongkut's Institute of Technology Ladkrabang, one of Thailand's leading technical universities, and that university affiliation shapes the school's identity directly: it is explicitly STEAM-focused, built around science, technology, engineering, arts, and math rather than a general academic curriculum.\n\nThe school holds accreditation from the Western Association of Schools and Colleges, giving it a US-standard accreditation despite its Thai university-affiliated origins, and its graduates have gone on to universities including Chulalongkorn, Mahidol, and Keio, reflecting both strong local and Asian regional university outcomes.\n\nBeing tied to a technical university gives KMIDS a genuine academic specialization that most general international schools in Bangkok do not have, appealing specifically to families whose children show strong interest or aptitude in STEM subjects from an early stage.\n\nFamilies choosing KMIDS are typically doing so specifically for its STEAM focus and university affiliation, rather than comparing it directly against Bangkok's more general British, American, or IB curriculum schools.", languageOfInstruction: "English" },
  { name: "The Jataka School", slug: "the-jataka-school", curricula: ["British", "Buddhist"], budget: "under400k", website: "https://www.thejatakaschool.com", description: "The Jataka School combines British curriculum academics with a Buddhist values-based approach to education, joining Roong Aroon among Bangkok's schools that blend a mainstream international curriculum with explicit Buddhist principles rather than operating as a purely secular institution.\n\nThat combination of British curriculum structure with Buddhist values grounding is a distinctive positioning, appealing specifically to families who want their children's education to include that spiritual and ethical dimension alongside standard IGCSE or A-Level academics.\n\nAs a smaller school with this specific values-based approach, The Jataka School likely offers a more intimate community than Bangkok's larger secular British curriculum schools, similar in spirit to how Roong Aroon differentiates itself within the IB space.\n\nFamilies drawn to The Jataka School are typically specifically seeking that blend of British academic structure and Buddhist values, rather than comparing it directly against Bangkok's larger, purely secular international schools.", languageOfInstruction: "English" },
  { name: "Sarasas Ektra School", slug: "sarasas-ektra-school", curricula: ["Catholic", "International", "Thai"], budget: "unknown", website: "https://www.ektra.ac.th", description: "Sarasas Ektra is part of the long-running Sarasas school network in Thailand, combining Catholic educational values with an international, bilingual Thai-English program, giving it institutional backing from an established Thai school group rather than operating as a fully independent international school.\n\nThat Sarasas network affiliation means Ektra benefits from shared resources and a long institutional history within Thailand's broader private education landscape, even as its specific international, bilingual program serves a different audience than the network's more purely Thai-curriculum schools.\n\nThe combination of Catholic values with bilingual Thai-English instruction is a distinctive positioning within Bangkok's international school market, most of which is either secular or tied to Protestant Christian denominations rather than Catholic specifically.\n\nFamilies specifically seeking a Catholic, bilingual Thai-English education, backed by an established local school network, would consider Sarasas Ektra alongside Bangkok's smaller number of other faith-based bilingual options.", languageOfInstruction: "English, Thai" },
  { name: "AIT International School", slug: "ait-international-school", curricula: ["American"], budget: "under400k", description: "AIT International School is an American-curriculum school in Bangkok, part of the city's wide range of US-accredited school options, operating independently of the larger American school networks like ASB or the various international groups present in the city.\n\nAs an independently branded American curriculum school, AIT likely shapes its own specific program and culture without the shared institutional resources that come with being part of a larger network, similar to Berkeley or NIVA in that respect.\n\nFamilies researching AIT should confirm current curriculum details, AP course availability, and fees directly with the school, since detailed public information is more limited than for Bangkok's largest American schools like ISB.\n\nFamilies comparing AIT against Bangkok's other independently run American schools are typically weighing location and specific program details rather than network brand recognition.", languageOfInstruction: "English", photo: "/images/schools/ait-international-school.jpg" },
  { name: "St. Andrews Samakee International School", slug: "st-andrews-samakee-international-school", curricula: ["British"], budget: "over400k", website: "https://www.standrews-samakee.com", description: "St. Andrews Samakee is a British-curriculum school in Bangkok, part of the city's range of St. Andrews-branded and British-style education providers, though families should note that multiple unrelated school groups use the St. Andrews name in Bangkok, including both the Nord Anglia-owned campus and the separate Cognita-owned Sathorn, Sukhumvit 107, and Dusit campuses.\n\nGiven that naming overlap across at least three separate ownership groups in the city, families researching St. Andrews Samakee specifically should confirm its ownership and institutional affiliation directly, since the shared branding does not indicate any operational connection between these schools.\n\nAs with any British curriculum school in Bangkok, families should confirm the specific examination pathway, whether IGCSE and A-Levels or an alternative structure, along with current fees and admissions requirements directly with the school.\n\nFamilies interested in St. Andrews Samakee should treat it as a distinct institution from Bangkok's other St. Andrews-named schools, evaluating its specific program on its own merits rather than assuming shared quality or curriculum with the differently owned campuses sharing the name.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Sukhumvit 107", slug: "st-andrews-international-school-sukhumvit-107", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://www.standrewssukhumvit.com", founded: 1996, description: "Established in 1996 near Bearing BTS station in Bang Na, this is the only one of Bangkok's three Cognita-owned St Andrews campuses to offer both primary and secondary education on a single site, combining the English National Curriculum with the IB Diploma Programme in the senior years.\n\nBecause it is the secondary destination for students coming from both the Sathorn and Dusit primary-only campuses within the same Cognita network, Sukhumvit 107 tends to be larger and more established than its sister campuses, with a longer track record specifically at the secondary level.\n\nThe combination of British curriculum through the primary and IGCSE years, followed by an IB Diploma option rather than A-Levels, is a structural choice shared with a handful of other Bangkok schools like Regent's and Bangkok Patana.\n\nAs with the other Cognita St Andrews campuses, families should be careful to distinguish this school from the separate, unrelated Nord Anglia-owned St Andrews International School Bangkok despite the shared name.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Knightsbridge House International School Nonthaburi", slug: "knightsbridge-house-international-school-nonthaburi", curricula: ["British"], budget: "under400k", website: "https://kbh.ac.th", description: "Knightsbridge House is a British-curriculum school located in Nonthaburi, just outside central Bangkok, serving families in the northern greater Bangkok area who may prefer a shorter commute over a central Sukhumvit location.\n\nAs a Nonthaburi-based school, Knightsbridge House joins a smaller cluster of international schools in that part of greater Bangkok, including ISB itself, which is also located in Nonthaburi's Nichada Thani community, though Knightsbridge House operates as a considerably smaller, independent school by comparison.\n\nFamilies already living in or near Nonthaburi, rather than the central Bangkok expat corridor, are the natural audience for Knightsbridge House, prioritizing proximity over the scale and brand recognition of the city's larger central schools.\n\nFamilies interested in Knightsbridge House should confirm current curriculum details, fees, and admissions directly with the school, as with any of Bangkok's smaller, independently run international schools.", languageOfInstruction: "English" },
  { name: "Raffles American School Bangkok", slug: "raffles-american-school-bangkok", curricula: ["American"], budget: "under400k", website: "https://ras.ac.th", founded: 2012, description: "Raffles American School, founded in 2012, is located in Samut Prakan just outside Bangkok's city limits and is part of the Raffles Education Group network, a Singapore-based education company operating schools across multiple countries in Asia.\n\nThe school offers a US-accredited curriculum from Pre-K through Grade 12, leading to a US high school diploma, with AP course options available for students pursuing university applications that benefit from advanced coursework.\n\nBeing part of the larger Raffles Education Group gives the school access to institutional resources and curriculum consistency shared across the group's other campuses internationally, similar in structure to how SISB or Global Indian International School benefit from their own larger networks.\n\nThe Samut Prakan location places Raffles American School outside the central Bangkok cluster of international schools, making it a practical choice for families based in that area or willing to accept a longer commute for the specific program and network backing it offers.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "RC International School", slug: "rc-international-school", curricula: ["British"], budget: "under400k", website: "https://www.rcis.ac.th", description: "RC International School is a British-curriculum school in Bangkok, offering families another option among the city's many providers of the National Curriculum for England, operating independently of the larger UK-affiliated networks like Nord Anglia or Cognita.\n\nAs an independently branded school, RC International likely has more flexibility in shaping its own specific culture and program details than schools tied into a larger international network, though this also means less access to shared institutional resources.\n\nFamilies researching RC International should confirm current curriculum structure, examination pathway, and fees directly with the school, since detailed public information is more limited than for Bangkok's larger, more established international schools.\n\nFamilies comparing RC International against Bangkok's other independently run British curriculum schools are typically weighing location and specific program fit rather than brand name or network affiliation.", languageOfInstruction: "English" },
  { name: "Roong Aroon International School", slug: "roong-aroon-international-school", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.roongaroonis.ac.th", founded: 1997, description: "Roong Aroon is a non-profit school on a 20-acre green campus in the Bang Khun Thian district, grounded explicitly in Buddhist values and experiential, holistic learning rather than a purely exam-focused academic model, which sets it apart from most of Bangkok's other IB schools.\n\nFounded in 1997, it is an IB World School offering the Middle Years Programme, built on an Australian curriculum base, and the Career-related Programme for students in Grades 11 and 12 who want a more vocationally oriented pathway than the standard IB Diploma.\n\nThe combination of a large green campus, non-profit structure, and explicit Buddhist values framework makes Roong Aroon a genuinely different option from Bangkok's more conventional British, American, or purely secular IB schools, appealing specifically to families who want that values-based, experiential approach.\n\nFamilies drawn to Roong Aroon are typically prioritizing its specific combination of holistic, values-driven education and campus space over the more traditional academic-first positioning of most other international schools in the city.", languageOfInstruction: "English, Thai" },
  { name: "Satit Bilingual School of Rangsit University", slug: "satit-bilingual-school-of-rangsit-university", curricula: ["British", "International Baccalaureate"], budget: "under400k", website: "https://sbs.ac.th", description: "SBS Rangsit, located in Pathum Thani, combines the IB Primary Years Programme with Cambridge IGCSE and A-Levels in the secondary years, giving students an IB-style foundation followed by a British examination pathway rather than continuing into the IB Diploma itself.\n\nThe school teaches bilingually in Thai and English, with Chinese offered as an additional language, giving students a genuinely trilingual academic environment similar in spirit to SISB's approach, though built around a different core curriculum combination.\n\nBeing affiliated with Rangsit University gives SBS students a pathway to earn pre-university credit that can count toward admission at Rangsit and potentially other Thai and international universities, a specific practical benefit tied to its university affiliation that standalone K-12 schools cannot offer.\n\nFamilies drawn to SBS Rangsit are typically interested in that specific combination of IB primary teaching, a British secondary exam pathway, genuine Thai-English-Chinese trilingual instruction, and the university credit pathway through Rangsit.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Thai" },
  { name: "Montessori Academy Bangkok International School", slug: "montessori-academy-bangkok-international-school", curricula: ["American", "Montessori"], budget: "over400k", website: "https://www.montessoribkk.com", description: "Montessori Academy Bangkok is an American-curriculum school built around Montessori teaching principles, blending child-led, self-directed learning methods with a structured American academic framework rather than following a purely traditional classroom model.\n\nThat Montessori approach specifically emphasizes hands-on learning materials and mixed-age classrooms where children work at their own pace, a meaningfully different pedagogical philosophy from the more conventional grade-by-grade instruction most Bangkok international schools use.\n\nFamilies specifically seeking Montessori methodology within an American curriculum framework, rather than a standard American school structure, are the natural audience for Montessori Academy Bangkok.\n\nFamilies interested should confirm current age ranges served and whether the school extends the Montessori approach through primary and secondary levels or focuses primarily on the early years, since Montessori programs vary in how far through a child's education they carry that specific method.", languageOfInstruction: "English" },
  { name: "Pensmith School", slug: "pensmith-school", curricula: ["British"], budget: "unknown", website: "https://pensmithschool.com", description: "Pensmith School is a British-curriculum school in Bangkok, part of the city's broad mix of smaller National Curriculum for England providers operating independently of the larger UK-affiliated school networks.\n\nAs a smaller, independently run school, Pensmith likely offers a more intimate community than Bangkok's larger British schools, though families should confirm specific class sizes, facilities, and examination pathway directly with the school.\n\nDetailed public information on Pensmith's specific history, fees, and track record is more limited than for Bangkok's larger, more established international schools, so families interested should plan on contacting the school directly.\n\nFamilies comparing Pensmith against Bangkok's other smaller, independently run British curriculum schools are typically weighing location and specific program fit over brand name recognition.", languageOfInstruction: "English" },
  { name: "Bangkok-Chicago Christian International School", slug: "bangkok-chicago-christian-international-school", curricula: ["American", "Christian"], budget: "unknown", website: "https://bcci.ac.th", description: "Bangkok-Chicago Christian International School is a Christian, American-curriculum school in Bangkok, combining faith-based values with a US-style academic program, joining ICS, Bangkok Christian International, Ekamai, and the Adventist schools among the city's faith-based American curriculum options.\n\nThe specific Chicago element in the school's name likely reflects an institutional or founding connection to that US city, though families should confirm the specific nature of that link directly with the school for accurate current details.\n\nAs one of several Christian American curriculum schools in Bangkok, Bangkok-Chicago Christian shares broad similarities with its faith-based peers while likely carrying its own specific denominational background and campus culture.\n\nFamilies specifically seeking a Christian, American curriculum education would compare Bangkok-Chicago Christian against Bangkok's other faith-based American schools on the basis of specific denomination, location, and campus community.", languageOfInstruction: "English" },
];

